:root {
  color-scheme: dark;
  --bg: #050606;
  --panel: #111111;
  --panel-2: #181818;
  --cream: #fffdf8;
  --ink: #242220;
  --muted: #9b9b9b;
  --line: rgba(255, 255, 255, 0.12);
  --soft-line: #e8e1d8;
  --gold: #f4ca32;
  --gold-2: #ffe562;
  --brown: #331710;
  --success: #40d36e;
  --danger: #ff6a3d;
  --shadow: 0 28px 80px rgba(0, 0, 0, 0.45);
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}

html {
  min-height: 100%;
  scrollbar-gutter: stable;
  background: #fff3fa;
}

html,
body,
#app {
  min-height: 100%;
}

#app {
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 78, 122, 0.16), transparent 30%),
    radial-gradient(circle at 86% 18%, rgba(94, 8, 108, 0.1), transparent 28%),
    linear-gradient(180deg, #fff3fa 0%, #fff8fc 48%, #f8efff 100%);
}

#app:empty::before {
  content: "";
  position: fixed;
  inset: 0;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 78, 122, 0.16), transparent 30%),
    radial-gradient(circle at 86% 18%, rgba(94, 8, 108, 0.1), transparent 28%),
    linear-gradient(180deg, #fff3fa 0%, #fff8fc 48%, #f8efff 100%);
}

/* Image Generator canvas studio */
.studio-shell .canvas-card:has(.image-canvas-studio) {
  padding: 0 !important;
  overflow: visible !important;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(255, 248, 252, 0.94)) !important;
}

.studio-shell .canvas-card:has(.image-higgsfield-mode) {
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.studio-shell .canvas-card:has(.video-prompt-extractor-page) {
  border: 0 !important;
  border-radius: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.studio-shell .workspace:has(.image-higgsfield-mode),
.studio-shell .workspace:has(.video-prompt-extractor-page) {
  padding: 0 0 64px !important;
  overflow-x: hidden;
}

.studio-shell .workspace:has(.image-higgsfield-mode) > *,
.studio-shell .workspace:has(.video-prompt-extractor-page) > * {
  width: 100% !important;
  max-width: 100% !important;
}

.image-canvas-studio {
  min-height: calc(100vh - 230px);
  display: grid;
  grid-template-rows: auto minmax(360px, 1fr) auto;
}

.image-studio-topbar {
  min-height: 70px;
  display: grid;
  grid-template-columns: minmax(220px, 0.8fr) auto minmax(420px, 1fr);
  align-items: center;
  gap: 14px;
  border-bottom: 1px solid rgba(57, 22, 67, 0.08);
  padding: 14px 18px;
}

.image-studio-topbar h2 {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0;
  color: var(--studio-purple-900, #260033);
  font-size: 22px;
  font-weight: 950;
  letter-spacing: 0;
}

.image-studio-topbar > div:first-child span {
  display: block;
  margin-top: 3px;
  color: rgba(83, 62, 90, 0.58);
  font-size: 12px;
  font-weight: 850;
}

.image-studio-tabs {
  display: inline-flex;
  gap: 6px;
  border-radius: 14px;
  padding: 5px;
  background: rgba(57, 22, 67, 0.045);
}

.image-studio-tabs button {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 0;
  border-radius: 11px;
  padding: 0 14px;
  background: transparent;
  color: rgba(57, 22, 67, 0.58);
  font-size: 13px;
  font-weight: 900;
}

.image-studio-tabs button.active,
.image-studio-tabs button:hover {
  background: #fff;
  color: var(--studio-purple-900, #260033);
  box-shadow: 0 10px 24px rgba(57, 22, 67, 0.08);
}

.image-studio-models {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.image-studio-models label,
.image-console-tools label {
  min-width: 0;
  margin: 0;
  color: transparent;
  font-size: 0;
}

.image-studio-models select,
.image-console-tools select {
  width: 100%;
  min-height: 42px;
  border: 1px solid rgba(57, 22, 67, 0.12);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.92);
  color: var(--studio-purple-900, #260033);
  font-size: 14px;
  font-weight: 900;
}

.image-canvas-stage {
  min-height: 420px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 270px);
  gap: 12px;
  padding: 12px;
}

.image-main-preview {
  min-height: 100%;
  display: grid;
  grid-template-rows: minmax(260px, 1fr) auto;
  overflow: hidden;
  border: 1px solid rgba(57, 22, 67, 0.1);
  border-radius: 18px;
  background:
    linear-gradient(rgba(57, 22, 67, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(57, 22, 67, 0.035) 1px, transparent 1px),
    radial-gradient(circle at 85% 12%, rgba(255, 63, 110, 0.13), transparent 34%),
    #fff;
  background-size: 42px 42px, 42px 42px, auto, auto;
}

.image-preview-frame {
  min-height: 0;
  display: grid;
  place-items: center;
  padding: 16px;
}

.image-preview-frame img,
.image-preview-frame video {
  max-width: 100%;
  max-height: min(62vh, 620px);
  border-radius: 14px;
  object-fit: contain;
  box-shadow: 0 18px 48px rgba(35, 8, 42, 0.12);
}

.image-main-preview footer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 14px;
  border-top: 1px solid rgba(57, 22, 67, 0.08);
  padding: 14px 16px;
  background: rgba(255, 255, 255, 0.9);
}

.image-main-preview footer b {
  display: block;
  color: var(--studio-purple-900, #260033);
  font-size: 15px;
  font-weight: 950;
}

.image-main-preview footer span {
  display: block;
  overflow: hidden;
  margin-top: 4px;
  color: rgba(83, 62, 90, 0.66);
  font-size: 13px;
  font-weight: 760;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-preview-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.image-preview-actions button,
.image-empty-canvas button {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgba(255, 47, 109, 0.16);
  border-radius: 10px;
  padding: 0 11px;
  background: #fff;
  color: var(--studio-purple-900, #260033);
  font-size: 12px;
  font-weight: 900;
}

.image-empty-canvas {
  grid-template-rows: 1fr;
  place-items: center;
  padding: 30px;
  text-align: center;
}

.image-empty-canvas > div {
  max-width: 640px;
  display: grid;
  justify-items: center;
  gap: 14px;
}

.image-empty-canvas b {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--studio-purple-900, #260033);
  font-size: clamp(24px, 3vw, 38px);
  font-weight: 950;
}

.image-empty-canvas p {
  margin: 0;
  color: rgba(83, 62, 90, 0.66);
  font-size: 15px;
  font-weight: 760;
}

.image-empty-canvas div div {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.image-empty-canvas button {
  border-radius: 999px;
  background: rgba(255, 247, 252, 0.92);
  color: var(--hot);
}

.image-history-rail {
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  border: 1px solid rgba(57, 22, 67, 0.1);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.76);
}

.image-history-rail header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(57, 22, 67, 0.08);
  padding: 12px;
}

.image-history-rail header b {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--studio-purple-900, #260033);
  font-size: 13px;
  font-weight: 950;
}

.image-history-rail header span {
  color: rgba(83, 62, 90, 0.6);
  font-size: 12px;
  font-weight: 900;
}

.image-history-rail > div {
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: start;
  gap: 8px;
  overflow: auto;
  padding: 10px;
}

.image-history-thumb {
  min-width: 0;
  aspect-ratio: 1 / 1.18;
  position: relative;
  overflow: hidden;
  border: 2px solid transparent;
  border-radius: 13px;
  padding: 0;
  background: rgba(57, 22, 67, 0.055);
}

.image-history-thumb.active {
  border-color: var(--hot);
}

.image-history-thumb img,
.image-history-thumb video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-history-thumb small {
  position: absolute;
  inset: auto 6px 6px;
  overflow: hidden;
  border-radius: 8px;
  padding: 5px 7px;
  background: rgba(31, 6, 38, 0.68);
  color: #fff;
  font-size: 10px;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-history-thumb.pending {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  color: var(--hot);
}

.image-history-thumb.pending b {
  color: var(--studio-purple-900, #260033);
  font-size: 11px;
}

.image-history-thumb.pending {
  isolation: isolate;
  align-content: stretch;
  justify-items: stretch;
  gap: 6px;
  padding: 9px;
  color: #fff;
  background:
    radial-gradient(circle at 25% 16%, rgba(255, 112, 176, 0.25), transparent 34%),
    radial-gradient(circle at 78% 80%, rgba(255, 211, 92, 0.1), transparent 30%),
    linear-gradient(145deg, #7a2389 0%, #481154 58%, #26072f 100%);
}

.image-history-thumb.pending::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0.24;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.08) 1px, transparent 1px);
  background-size: 18px 18px;
  pointer-events: none;
}

.image-history-cancel-generation {
  position: absolute;
  top: 7px;
  right: 7px;
  z-index: 4;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 11px;
  padding: 0;
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(10px);
}

.image-history-pending-preview {
  position: relative;
  z-index: 1;
  min-height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 13px;
  margin-top: 28px;
  background:
    radial-gradient(circle at 50% 46%, rgba(255, 255, 255, 0.15), transparent 38%),
    rgba(255, 255, 255, 0.07);
  overflow: hidden;
}

.image-history-pending-preview i {
  position: absolute;
  display: block;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
  animation: pending-shimmer 2.2s ease-in-out infinite;
}

.image-history-pending-preview i:nth-child(1) {
  left: 13%;
  top: 19%;
  width: 50%;
  height: 6px;
}

.image-history-pending-preview i:nth-child(2) {
  left: 18%;
  top: 43%;
  width: 64%;
  height: 7px;
  animation-delay: 0.18s;
}

.image-history-pending-preview i:nth-child(3) {
  left: 22%;
  top: 67%;
  width: 42%;
  height: 6px;
  animation-delay: 0.36s;
}

.image-history-pending-preview span {
  z-index: 2;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  backdrop-filter: blur(10px);
}

.image-history-thumb.pending b,
.image-history-thumb.pending small,
.image-history-thumb.pending em {
  position: relative;
  z-index: 1;
  min-width: 0;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
}

.image-history-thumb.pending b {
  color: #fff;
  font-size: 12px;
  font-weight: 950;
  line-height: 1.05;
  white-space: nowrap;
}

.image-history-thumb.pending small {
  position: static;
  display: -webkit-box;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: rgba(255, 246, 255, 0.78);
  font-size: 10px;
  font-weight: 780;
  line-height: 1.2;
  white-space: normal;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.image-history-thumb.pending em {
  display: block;
  border-radius: 9px;
  padding: 6px 7px;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.64);
  font-size: 9px;
  font-style: normal;
  font-weight: 760;
  line-height: 1.15;
  white-space: nowrap;
}

.image-generate-console {
  position: sticky;
  bottom: 0;
  z-index: 10;
  display: grid;
  grid-template-columns: minmax(118px, 0.42fr) 54px minmax(380px, 1.45fr) minmax(220px, 0.52fr) minmax(210px, 0.48fr) minmax(150px, 0.36fr);
  align-items: stretch;
  gap: 10px;
  border-top: 1px solid rgba(57, 22, 67, 0.1);
  border-radius: 22px 22px 0 0;
  padding: 12px;
  background:
    radial-gradient(circle at 92% 0, rgba(255, 63, 110, 0.12), transparent 34%),
    rgba(255, 255, 255, 0.96);
  box-shadow: 0 -18px 48px rgba(35, 8, 42, 0.1);
  backdrop-filter: blur(16px);
}

.image-console-add,
.image-console-generate,
.image-reference-thumb,
.image-console-tools span {
  border: 1px solid rgba(57, 22, 67, 0.1);
  border-radius: 14px;
}

.studio-bottom-step-menu {
  width: min(360px, 100%);
}

.studio-bottom-step-menu summary {
  min-height: 78px;
  padding: 0 18px;
}

.studio-immersive-page {
  min-height: calc(100vh - 72px);
  position: relative;
  display: grid;
  grid-template-rows: minmax(420px, 1fr) auto auto;
  gap: 16px;
  padding-bottom: 0;
}

.studio-wall-zoom-control {
  position: absolute;
  z-index: 6;
  top: 10px;
  right: 12px;
  width: clamp(92px, 8vw, 128px);
  height: 14px;
  min-height: 14px;
  overflow: visible;
  border: 0;
  border-radius: 999px;
  padding: 0;
  background: transparent;
  box-shadow: none;
}

.studio-wall-zoom-control::before,
.studio-wall-zoom-control::after {
  content: "";
  position: absolute;
  pointer-events: none;
}

.studio-wall-zoom-control::before {
  left: 0;
  right: 0;
  top: 6px;
  height: 2px;
  border-radius: 999px;
  background:
    linear-gradient(90deg, rgba(255, 250, 252, 0.92) var(--studio-wall-zoom-progress, 50%), rgba(255, 250, 252, 0.26) 0);
  box-shadow: 0 1px 4px rgba(35, 8, 42, 0.18);
}

.studio-wall-zoom-control::after {
  top: 1px;
  left: var(--studio-wall-zoom-progress, 50%);
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: #fff;
  box-shadow: 0 3px 8px rgba(35, 8, 42, 0.2);
  transform: translateX(-50%);
}

.studio-wall-zoom-control input[type="range"] {
  position: absolute;
  inset: -8px -10px;
  width: 100%;
  height: 30px;
  margin: 0;
  -webkit-appearance: none;
  appearance: none;
  opacity: 0;
  background: transparent !important;
  border: 0;
  cursor: ew-resize;
}

.studio-wall-zoom-control input[type="range"]::-webkit-slider-runnable-track {
  -webkit-appearance: none;
  height: 30px;
  background: transparent;
}

.studio-wall-zoom-control input[type="range"]::-webkit-slider-thumb {
  width: 20px;
  height: 30px;
  -webkit-appearance: none;
  background: transparent;
}

.studio-wall-zoom-control input[type="range"]::-moz-range-track {
  height: 30px;
  background: transparent;
}

.studio-wall-zoom-control input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 30px;
  border: 0;
  background: transparent;
}

.studio-result-wall {
  min-height: min(62vh, 720px);
  overflow: hidden;
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.68);
  background:
    radial-gradient(circle at 18% 12%, rgba(255, 47, 109, 0.16), transparent 30%),
    radial-gradient(circle at 82% 4%, rgba(215, 255, 64, 0.16), transparent 28%),
    rgba(255, 255, 255, 0.62);
  box-shadow: 0 24px 80px rgba(35, 8, 42, 0.12);
}

.studio-wall-grid {
  height: 100%;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(var(--studio-wall-column, 260px), 100%), 1fr));
  grid-auto-rows: clamp(180px, calc(var(--studio-wall-column, 260px) * 0.9), 420px);
  gap: 8px;
  padding: 8px;
}

.studio-wall-card {
  position: relative;
  overflow: hidden;
  contain: layout paint;
  border-radius: 14px;
  background: rgba(31, 6, 38, 0.08);
  color: #fff;
}

.studio-wall-card:nth-child(2),
.studio-wall-card:nth-child(7) {
  grid-row: span 2;
}

.studio-wall-card:nth-child(3),
.studio-wall-card:nth-child(8) {
  grid-column: span 2;
}

.studio-wall-card .result-preview-trigger,
.studio-wall-card .result-image,
.studio-wall-card .result-video,
.studio-wall-card .result-video-shell,
.studio-wall-card .visual-card-preview,
.studio-wall-card .result-text-preview,
.studio-wall-card .result-media-error {
  width: 100% !important;
  height: 100% !important;
  min-height: 100% !important;
  border-radius: 0 !important;
  object-fit: cover !important;
}

.studio-wall-card footer {
  position: absolute;
  inset: auto 10px 10px;
  display: grid;
  gap: 3px;
  border-radius: 12px;
  padding: 9px 10px;
  background: rgba(15, 15, 15, 0.72);
  color: #fff;
  backdrop-filter: blur(12px);
}

.studio-wall-card footer b,
.studio-wall-card footer span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.studio-wall-card footer b {
  font-size: 13px;
  font-weight: 950;
}

.studio-wall-card footer span {
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
  font-weight: 750;
}

.studio-wall-pending div {
  display: grid;
  place-items: center;
  gap: 10px;
  color: rgba(31, 6, 38, 0.72);
  font-weight: 950;
}

.studio-wall-pending {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.72);
}

.studio-advanced-drawer {
  border: 1px solid rgba(57, 22, 67, 0.08);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--studio-purple-900, #260033);
}

.studio-advanced-drawer summary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 16px;
  color: rgba(57, 22, 67, 0.72);
  font-weight: 950;
  cursor: pointer;
}

.studio-advanced-drawer > div {
  padding: 0 16px 16px;
}

.studio-generate-dock {
  position: sticky;
  bottom: 0;
  z-index: 18;
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) minmax(150px, 0.22fr);
  gap: 12px;
  align-items: stretch;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 24px 24px 0 0;
  padding: 14px;
  background: rgba(18, 20, 20, 0.94);
  box-shadow: 0 -22px 70px rgba(10, 5, 13, 0.22);
  backdrop-filter: blur(18px);
}

.studio-dock-add,
.studio-dock-generate,
.studio-dock-tools span {
  border-radius: 14px;
}

.studio-dock-add {
  min-height: 48px;
  border: 1px solid rgba(215, 255, 64, 0.18);
  background: rgba(255, 255, 255, 0.04);
  color: #fff;
}

.studio-dock-main {
  display: grid;
  gap: 10px;
}

.studio-dock-prompt textarea,
.studio-dock-prompt input {
  width: 100%;
  min-height: 52px;
  border: 0;
  outline: 0;
  resize: none;
  padding: 14px 2px;
  background: transparent;
  color: #fff;
  font-size: 18px;
  font-weight: 760;
}

.studio-dock-prompt textarea::placeholder,
.studio-dock-prompt input::placeholder {
  color: rgba(255, 255, 255, 0.42);
}

.studio-dock-tools {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.studio-dock-tools span {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 0 14px;
  background: rgba(255, 255, 255, 0.045);
  color: rgba(255, 255, 255, 0.78);
  font-size: 13px;
  font-weight: 850;
}

