  filter: drop-shadow(0 1px 8px rgba(82, 0, 54, 0.24));
  stroke-width: 2.4;
}

/* Image console brand pass: controlled Pokaya dark surface with pink/coral action. */
.studio-shell .image-generate-console {
  border-top: 1px solid rgba(255, 210, 232, 0.18);
  background:
    radial-gradient(circle at 82% 0, rgba(255, 49, 95, 0.2), transparent 32%),
    linear-gradient(135deg, rgba(34, 0, 45, 0.98), rgba(48, 0, 62, 0.96) 54%, rgba(31, 0, 41, 0.98));
  box-shadow:
    0 -24px 70px rgba(34, 0, 45, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.studio-shell .image-console-add,
.studio-shell .image-console-tools span,
.studio-shell .image-console-tools .image-aspect-ratio-select,
.studio-shell .image-console-tools .image-resolution-select,
.studio-shell .image-reference-thumb,
.studio-shell .image-console-tools select,
.studio-shell .image-console-step-menu summary {
  border-color: rgba(255, 250, 252, 0.14);
  background: rgba(255, 250, 252, 0.065);
  color: rgba(255, 250, 252, 0.86);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 10px 26px rgba(20, 0, 27, 0.22);
}

.studio-shell .image-console-add:hover,
.studio-shell .image-reference-thumb:hover,
.studio-shell .image-console-step-menu summary:hover {
  border-color: rgba(255, 49, 95, 0.42);
  background: rgba(255, 49, 95, 0.12);
  transform: translateY(-1px);
}

.studio-shell .image-console-add,
.studio-shell .image-reference-thumb,
.studio-shell .image-console-step-menu summary,
.studio-shell .image-console-generate {
  transition: transform 180ms ease, border-color 180ms ease, background 180ms ease, box-shadow 180ms ease;
}

.studio-shell .image-console-prompt textarea {
  border-color: rgba(255, 250, 252, 0.18);
  background:
    linear-gradient(180deg, rgba(255, 250, 252, 0.98), rgba(255, 243, 248, 0.98));
  color: #2a1033;
  box-shadow:
    inset 0 0 0 1px rgba(255, 49, 95, 0.08),
    0 16px 34px rgba(20, 0, 27, 0.2);
}

.studio-shell .image-console-prompt textarea:focus {
  border-color: rgba(255, 49, 95, 0.52);
  box-shadow:
    0 0 0 3px rgba(255, 49, 95, 0.18),
    0 16px 34px rgba(20, 0, 27, 0.22);
}

.studio-shell .image-console-prompt textarea::placeholder {
  color: rgba(42, 16, 51, 0.46);
}

.studio-shell .image-console-tools span {
  color: rgba(255, 250, 252, 0.78);
}

.studio-shell .image-console-tools span svg,
.studio-shell .image-console-tools .image-aspect-ratio-select svg,
.studio-shell .image-console-tools .image-resolution-select svg,
.studio-shell .image-console-add svg,
.studio-shell .image-reference-thumb svg,
.studio-shell .image-console-step-menu summary svg {
  color: #b78ad8;
  stroke: currentColor;
}

.studio-shell .image-reference-thumb .attachment-placeholder,
.studio-shell .image-reference-thumb > span:not(.image-reference-clear) {
  background: linear-gradient(135deg, rgba(255, 250, 252, 0.98), rgba(255, 243, 248, 0.94));
  color: #ff315f;
}

.studio-shell .image-reference-thumb.has-ref {
  border-color: rgba(255, 49, 95, 0.36);
  background: rgba(255, 49, 95, 0.12);
}

.studio-shell .image-reference-thumb b,
.studio-shell .image-console-step-menu summary b {
  color: #fffafc;
}

.studio-shell .image-reference-thumb small,
.studio-shell .image-console-step-menu summary small {
  color: rgba(255, 250, 252, 0.62);
}

.studio-shell .image-console-generate {
  border-color: rgba(255, 210, 26, 0.28);
  background:
    linear-gradient(135deg, #ff315f 0%, #ff765d 100%);
  box-shadow:
    0 18px 38px rgba(255, 49, 95, 0.36),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

.studio-shell .image-console-generate:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow:
    0 22px 44px rgba(255, 49, 95, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

.studio-shell .image-console-generate:active:not(:disabled) {
  transform: translateY(0) scale(0.99);
}

.image-studio-legacy {
  padding: 18px;
}

@media (max-width: 1180px) {
  .image-studio-topbar,
  .image-canvas-stage,
  .image-generate-console {
    grid-template-columns: 1fr;
  }

  .image-history-rail > div {
    grid-template-columns: repeat(4, minmax(110px, 1fr));
    overflow-x: auto;
  }
}

@media (max-width: 680px) {
  .image-canvas-stage {
    padding: 8px;
  }

  .image-main-preview footer {
    grid-template-columns: 1fr;
  }

  .image-history-rail > div,
  .image-console-references,
  .image-console-tools {
    grid-template-columns: 1fr 1fr;
  }

  .image-generate-console {
    border-radius: 18px 18px 0 0;
    padding: 10px;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--bg);
  color: white;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

.loading,
.login-shell,
.public-shell {
  min-height: 100vh;
  background:
    radial-gradient(
      circle at 72% 18%,
      rgba(244, 202, 50, 0.16),
      transparent 28%
    ),
    var(--bg);
}

.login-shell {
  display: grid;
  align-items: start;
  justify-items: center;
  padding: clamp(28px, 7vh, 72px) 16px 40px;
}

.public-shell {
  padding: 0 clamp(18px, 4vw, 64px) 64px;
}

.promo-bar {
  width: min(1180px, 100%);
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin: 0 auto;
  color: #080808;
  background: var(--gold-2);
  font-weight: 950;
  text-align: center;
}

.loading {
  gap: 12px;
  align-content: center;
  color: var(--gold);
  font-weight: 800;
}

.login-card {
  width: min(520px, calc(100vw - 32px));
  padding: 30px 34px 34px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(18, 18, 18, 0.94);
  box-shadow: var(--shadow);
}

.login-card h1 {
  font-size: clamp(34px, 4.8vw, 52px);
  line-height: 0.98;
}

.login-form {
  display: grid;
  gap: 18px;
}

.brand-lockup {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 28px;
}

.public-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  max-width: 1180px;
  margin: 0 auto 24px;
  padding: 28px 0;
}

.public-nav .brand-lockup {
  margin-bottom: 0;
}

.public-links {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-left: auto;
}

.nav-actions {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex: 0 0 auto;
}

.lang-menu {
  position: relative;
  display: inline-flex;
  z-index: 35;
}

.lang-switch {
  display: inline-grid;
  grid-template-columns: 15px auto auto 14px;
  align-items: center;
  gap: 7px;
  min-width: 112px;
  min-height: 42px;
  border: 1px solid rgba(95, 0, 103, 0.12);
  border-radius: 8px;
  padding: 8px 11px;
  background: rgba(255, 255, 255, 0.86);
  color: var(--purple);
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
  box-shadow: 0 10px 24px rgba(76, 0, 87, 0.06);
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease,
    transform 0.18s ease;
}

.lang-switch:hover {
  border-color: rgba(255, 79, 101, 0.24);
  background: #fff1f7;
  box-shadow: 0 12px 28px rgba(255, 79, 101, 0.12);
  transform: translateY(-1px);
}

.lang-switch span {
  min-width: 28px;
  text-align: right;
}

.lang-switch small {
  color: var(--muted);
  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.public-nav .lang-switch {
  grid-template-columns: 15px auto 14px;
  min-width: 78px;
  min-height: 46px;
  padding: 10px 11px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: none;
}

.public-nav .lang-switch small {
  display: none;
}

.lang-switch i {
  color: var(--muted);
  stroke-width: 3;
}

.lang-options {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  min-width: 146px;
  display: grid;
  gap: 4px;
  padding: 8px;
  border: 1px solid rgba(95, 0, 103, 0.12);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 18px 42px rgba(76, 0, 87, 0.14);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition:
    opacity 0.16s ease,
    transform 0.16s ease;
}

.lang-menu.open .lang-options {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.lang-options button {
  min-height: 36px;
  border: 0;
  border-radius: 10px;
  padding: 8px 12px;
  background: transparent;
  color: var(--purple);
  font-weight: 900;
  text-align: left;
}

.lang-options button:hover,
.lang-options button.active {
  background: #fff1f7;
  color: var(--pink);
}

.public-links a,
.public-footer a {
  color: #c9c2b8;
  text-decoration: none;
  font-weight: 800;
}

.public-hero {
  width: min(1180px, 100%);
  min-height: calc(100vh - 140px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 460px);
  align-items: center;
  gap: clamp(28px, 5vw, 76px);
  margin: 0 auto;
}

.public-hero h1 {
  max-width: 760px;
  margin-bottom: 20px;
  font-size: clamp(48px, 7vw, 94px);
}

.public-copy {
  max-width: 660px;
  color: #c9c2b8;
  font-size: clamp(18px, 2vw, 24px);
  line-height: 1.45;
}

.public-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 28px;
}

.trust-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
  color: #d8d1c8;
  font-weight: 850;
}

.trust-row span {
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
}

.hero-board,
.public-grid article,
.pain-list article,
.feature-mosaic article,
.compare-grid article,
.quote-grid article,
.price-card,
.lead-form,
.faq-section details {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(18, 18, 18, 0.92);
}

.hero-board {
  display: grid;
  gap: 16px;
  padding: 24px;
}

.race-card {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 18px;
  border-radius: 8px;
  background: #0a0a0a;
}

.race-card.hot {
  color: var(--gold);
}

.race-meter {
  height: 16px;
  overflow: hidden;
  border-radius: 999px;
  background: #242424;
}

.race-meter i {
  width: 76%;
  height: 100%;
  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--gold), var(--danger));
}

.public-grid,
.pain-list,
.feature-mosaic,
.compare-grid,
.quote-grid,
.pricing-section,
.signup-section {
  width: min(1180px, 100%);
  display: grid;
  gap: 18px;
  margin: 0 auto;
}

.public-grid {
  grid-template-columns: repeat(3, 1fr);
  padding: 34px 0 76px;
}

.public-grid article,
.pain-list article,
.feature-mosaic article,
.quote-grid article,
.price-card,
.lead-form {
  padding: 24px;
}

.public-grid span,
.feature-mosaic span,
.compare-grid span,
.price-card > span {
  color: var(--gold);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.18em;
