}

.public-grid p,
.pain-list p,
.feature-mosaic p,
.comparison-section p,
.testimonial-section p,
.pricing-section p,
.signup-section p,
.faq-section p {
  color: #c9c2b8;
  line-height: 1.55;
}

.split-section,
.feature-section,
.comparison-section,
.testimonial-section,
.faq-section {
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: 76px 0;
}

.split-section {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: 44px;
  align-items: start;
