}

.feature-mosaic article:nth-child(2),
.feature-mosaic article:nth-child(3),
.feature-mosaic article:nth-child(5) {
  grid-column: span 2;
}

.compare-grid {
  grid-template-columns: repeat(2, 1fr);
  margin-top: 28px;
}

.compare-grid article {
  padding: 28px;
}

.compare-grid .winner {
  border-color: rgba(244, 202, 50, 0.5);
