.demo-screen {
  min-height: 220px;
  display: grid;
  place-items: center;
  margin-bottom: 10px;
  border-radius: 8px;
  background:
    radial-gradient(circle at 50% 18%, rgba(244, 202, 50, 0.28), transparent 38%),
    linear-gradient(160deg, #2a2a2a, #070707);
  color: var(--gold);
}

.demo-reel span {
  color: var(--gold);
  font-weight: 950;
}

.demo-reel h3 {
  margin: 0;
  font-size: 22px;
  line-height: 1.05;
}

.demo-reel p {
  color: #c9c2b8;
}

.register-hero,
.affiliate-hero {
  width: min(1180px, 100%);
  min-height: 70vh;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 440px);
  align-items: center;
  gap: clamp(28px, 5vw, 76px);
  margin: 0 auto;
  padding: 44px 0 76px;
}

.register-hero h1,
.affiliate-hero h1 {
  max-width: 780px;
  margin-bottom: 22px;
  font-size: clamp(48px, 6vw, 88px);
  line-height: 0.96;
}

.checkout-steps {
  display: grid;
  gap: 14px;
  margin-top: 34px;
}

.checkout-steps article {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  gap: 4px 16px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(18, 18, 18, 0.92);
