}

.result-edit-form select:focus,
.result-edit-form textarea:focus {
  border-color: rgba(255, 94, 123, 0.72);
  box-shadow: 0 0 0 3px rgba(255, 94, 123, 0.12);
}

.result-edit-actions {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
}

.asset-library-head {
  align-items: end;
}

.asset-toolbar {
  margin-top: 18px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 16px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.86);
}

.asset-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.asset-filter-row button {
  min-height: 34px;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 999px;
  padding: 0 12px;
  background: #fff;
  color: #4f055f;
  font-size: 12px;
  font-weight: 900;
}

.asset-filter-row button.active {
  border-color: rgba(255, 47, 109, 0.28);
  background: #ff2f6d;
  color: #fff;
}

.result-grid button:not(.result-actions button):not(.result-workflow-actions button),
.table button,
.schedule-list button {
