  min-height: 110px;
  display: grid;
  place-items: center;
  color: #777;
}

.metric-row,
.topup-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 26px;
}

.metric-row article,
.topup-grid button {
  padding: 24px;
}

.metric-row span,
.table small,
.schedule-list small {
  color: #777;
}

.metric-row strong,
.topup-grid strong {
  display: block;
  font-size: 34px;
}

.table,
.schedule-list {
  display: grid;
  gap: 12px;
}

.table div,
.schedule-list article {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 14px;
  align-items: center;
  padding: 16px 18px;
}

.schedule-list article {
