  color: #280039;
  font-size: 22px;
  line-height: 1.15;
}

.autopost-job-main p {
  margin: 0;
  color: #625468;
  font-weight: 700;
  line-height: 1.45;
}

.autopost-job-main small {
  display: block;
  margin-top: 8px;
  color: #ff4f7b;
