  word-break: break-word;
}

.autopost-status-chip {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 5px 10px;
  border-radius: 999px;
  background: #f8e9f4;
  color: #280039;
  font-size: 12px;
  font-weight: 1000;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.autopost-job-meta {
  display: grid;
  justify-items: end;
  gap: 8px;
  min-width: 170px;
  color: #7b6d82;
