}

.autopost-job-meta b,
.autopost-job-meta span {
  display: inline-flex;
  gap: 6px;
  align-items: center;
}

.autopost-readiness {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.autopost-readiness span {
  display: inline-flex;
