  border: 1px solid #e8d6e7;
  border-radius: 8px;
  background: #fff;
  color: #280039;
  font-size: 13px;
  font-weight: 1000;
}

.autopost-job-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.autopost-side-card {
  display: grid;
  gap: 14px;
  padding: 18px;
  border: 1px solid #f4cde9;
