  align-items: center;
  color: #280039;
  font-size: 17px;
}

.setup-health-card p {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  margin: 0;
  color: #7b6d82;
}

.setup-health-card p[data-ok="true"] svg {
  color: #16a34a;
}

.setup-health-card p[data-ok="false"] svg {
