}

.setup-health-card span {
  display: grid;
  gap: 2px;
}

.setup-health-card b {
  color: #280039;
}

.setup-health-card small {
  color: #7b6d82;
  font-weight: 700;
  line-height: 1.35;
}

.publish-mode-card article {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid #f0d4ea;
  border-radius: 8px;
  background: #fffefa;
}

.publish-mode-card b {
  display: flex;
  gap: 8px;
  align-items: center;
  color: #280039;
}

.publish-mode-card p {
  margin: 0;
  color: #746377;
  font-weight: 700;
  line-height: 1.45;
  word-break: break-word;
}

.publish-mode-card details {
  color: #746377;
