}

.tiktok-publishes {
  display: grid;
  gap: 10px;
}

.tiktok-publishes article {
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid #f0d4ea;
  border-radius: 8px;
  background: #fffefa;
}

.tiktok-publishes span {
  color: #777;
