  justify-items: start;
  background: #fffefa;
  color: #171717;
  border-color: var(--soft-line);
}

.topup-grid b {
  color: var(--gold);
}

.chat-bubble {
  position: fixed;
  right: 28px;
  bottom: 28px;
  z-index: 25;
  width: 72px;
  height: 72px;
  border: 6px solid rgba(244, 202, 50, 0.28);
  border-radius: 50%;
  background: var(--gold);
  color: white;
  box-shadow: 0 0 42px rgba(244, 202, 50, 0.42);
}

.live-panel,
.chat-panel {
  position: fixed;
  right: 22px;
  z-index: 30;
  width: 320px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #121212;
  box-shadow: var(--shadow);
}

.live-panel {
  top: 33%;
}

.chat-panel {
  bottom: 140px;
}

.agent-panel {
  width: min(420px, calc(100vw - 28px));
  max-height: calc(100vh - 178px);
  display: grid;
  grid-template-rows: auto minmax(180px, 1fr) auto;
  gap: 14px;
  padding: 18px;
}

.agent-panel header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.agent-panel .icon-only {
  width: 38px;
  min-height: 38px;
  padding: 0;
  background: #1e1e1e;
  border-color: var(--line);
  color: #cfcfcf;
}

.agent-thread {
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-right: 4px;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.agent-thread article {
  display: grid;
  gap: 5px;
  max-width: 92%;
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #1a1a1a;
}

.agent-thread article.user {
  justify-self: end;
  background: rgba(244, 202, 50, 0.14);
  border-color: rgba(244, 202, 50, 0.32);
}

.agent-thread span,
.agent-empty {
  color: #8f8f8f;
  font-size: 12px;
  font-weight: 850;
}

.agent-thread p {
  margin: 0;
  color: #ededed;
  font-size: 14px;
  line-height: 1.45;
}

.agent-form {
  display: grid;
  gap: 10px;
}

.agent-form textarea {
  min-height: 48px;
  max-height: 132px;
  resize: none;
}

.live-panel h3,
.chat-panel h3 {
  display: flex;
  gap: 10px;
}

.live-panel p {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  color: #d6d6d6;
}

.chat-panel button {
  width: 100%;
  background: var(--gold);
  color: #080808;
  font-weight: 900;
}

.agent-panel .icon-only {
  width: 38px;
  min-height: 38px;
  background: #1e1e1e;
  color: #cfcfcf;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(0, 0, 0, 0.62);
}

.modal {
  position: relative;
  width: min(560px, 100%);
  padding: 30px;
  border-radius: 18px;
  background: var(--cream);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.modal h2 {
  color: var(--ink);
}

.attachment-picker-backdrop {
  background: rgba(0, 0, 0, 0.68);
  padding: clamp(18px, 4vh, 42px) clamp(18px, 4vw, 56px);
  overflow: hidden;
}

.attachment-picker-modal {
  width: min(72vw, 960px);
  max-height: min(74vh, 620px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 16px;
  background: #050505;
  color: #f8f8f8;
  box-shadow: 0 22px 70px rgba(0, 0, 0, 0.42);
}

.attachment-picker-body {
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}

.attachment-picker-head,
.attachment-picker-tabs {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 16px 22px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}

.attachment-picker-head h2 {
  margin: 0;
  color: #f4f1f5;
  font-size: 20px;
  letter-spacing: 0;
  text-transform: none;
}

.attachment-picker-head > div {
  display: flex;
  align-items: center;
  gap: 14px;
}

.attachment-add-button,
.attachment-picker-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 36px;
  border: 0;
  background: transparent;
  color: #d8d4da;
  font-size: 14px;
  font-weight: 900;
  cursor: pointer;
}

.attachment-add-button {
  color: #fff;
  text-shadow: 0 0 22px rgba(255, 255, 255, 0.22);
}

.attachment-add-button-product {
  color: #fff;
  text-shadow: 0 0 22px rgba(255, 255, 255, 0.22);
}

.attachment-add-button-avatar {
  color: #fff;
  text-shadow: 0 0 22px rgba(255, 255, 255, 0.22);
}

.attachment-picker-modal-avatar .attachment-add-button-avatar,
.attachment-picker-modal-avatar .attachment-add-button-avatar svg,
.attachment-picker-modal-avatar .attachment-add-button-avatar span {
  color: #ffffff !important;
}

.attachment-add-button:hover {
  color: #fff;
}

.attachment-add-button-product:hover {
  color: #fff;
}

.attachment-picker-close {
  width: 36px;
  color: #f8f8f8;
}

.attachment-picker-tabs {
  justify-content: flex-start;
  padding: 14px 22px;
}

.attachment-picker-tabs button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 18px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  background: transparent;
  color: #c6c0c9;
  font-size: 14px;
  font-weight: 950;
}

.attachment-picker-tabs button.active {
  border-color: #22c967;
  background: #22c967;
  color: #ffffff;
