.attachment-picker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 14px;
  min-height: 180px;
  overflow: visible;
  padding: 20px 22px 24px;
}

.attachment-picker-grid.is-locked {
