  padding-top: 0;
}

.attachment-upload-panel {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  margin: 18px 22px 14px;
  min-height: 96px;
  padding: 18px 20px;
  border: 1.5px dashed rgba(255, 255, 255, 0.26);
  border-radius: 18px;
  background:
