.attachment-upload-panel:hover,
.attachment-upload-panel.is-dragging {
  border-color: rgba(255, 95, 143, 0.78);
  background:
    radial-gradient(circle at 18% 50%, rgba(255, 95, 143, 0.18), transparent 34%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.02)),
    #090909;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.08),
    0 20px 58px rgba(95, 0, 103, 0.2);
  transform: translateY(-1px);
}

.attachment-upload-panel.product:hover,
.attachment-upload-panel.product.is-dragging {
  border-color: rgba(247, 184, 77, 0.82);
  background:
    radial-gradient(circle at 18% 50%, rgba(247, 184, 77, 0.16), transparent 34%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.02)),
    #090909;
}

.attachment-upload-panel-icon {
  display: grid;
  place-items: center;
  width: 54px;
  height: 54px;
  border-radius: 16px;
  background: rgba(255, 95, 143, 0.13);
  color: #ff8fb0;
  box-shadow: inset 0 0 0 1px rgba(255, 95, 143, 0.22);
}

.attachment-upload-panel.product .attachment-upload-panel-icon {
  background: rgba(247, 184, 77, 0.12);
  color: #ffd084;
  box-shadow: inset 0 0 0 1px rgba(247, 184, 77, 0.22);
}

.attachment-upload-panel strong {
  display: block;
  margin-bottom: 6px;
  color: #ffffff;
  font-size: 18px;
  font-weight: 950;
  letter-spacing: 0;
}

.attachment-upload-panel p {
  margin: 0;
  color: #aaa1ad;
  font-size: 14px;
  line-height: 1.4;
}

.attachment-upload-panel small {
  justify-self: end;
  color: #7e7484;
  font-size: 12px;
  font-weight: 850;
  white-space: nowrap;
}

.attachment-picker-card {
  position: relative;
  display: grid;
  gap: 10px;
  overflow: hidden;
  min-height: 206px;
  padding: 0 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 10px;
  background: #111111;
  color: #f8f8f8;
  text-align: left;
}

.attachment-picker-card:hover {
  border-color: #22c967;
  transform: translateY(-1px);
}

.attachment-picker-modal-product .attachment-picker-card:hover {
  border-color: #f7b84d;
}

.attachment-picker-modal-avatar .attachment-picker-card:hover {
  border-color: #ff7aa8;
}

.attachment-picker-card img,
.attachment-placeholder {
  width: 100%;
  aspect-ratio: 4 / 4.2;
  object-fit: cover;
  background: #171717;
}

.attachment-placeholder {
  display: grid;
  place-items: center;
  color: #7f6f86;
}

.attachment-kind-badge {
  position: absolute;
  z-index: 1;
  top: 12px;
  left: 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border-radius: 8px;
  background: #22c967;
  color: #ffffff;
  font-size: 11px;
  font-weight: 950;
}

.attachment-kind-badge.product {
  background: #f7b84d;
  color: #2b0634;
}

.attachment-kind-badge.avatar {
  background: #ff7aa8;
  color: #ffffff;
}

.attachment-picker-card b,
.attachment-picker-card small {
  padding: 0 12px;
}

.attachment-picker-card b {
  overflow: hidden;
  color: #f5f2f6;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attachment-picker-card small {
  display: -webkit-box;
  overflow: hidden;
  color: #b6aeb8;
  font-size: 12px;
  line-height: 1.35;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.attachment-picker-empty {
  grid-column: 1 / -1;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  min-height: 260px;
  border: 1.5px dashed rgba(255, 255, 255, 0.24);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.025), rgba(255, 255, 255, 0.01)),
    rgba(255, 255, 255, 0.012);
  color: #aaa1ad;
  cursor: copy;
  padding: 38px;
  text-align: center;
  transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.attachment-picker-empty:hover,
.attachment-picker-empty.is-dragging {
  border-color: rgba(255, 77, 123, 0.7);
  background:
    radial-gradient(circle at 50% 40%, rgba(255, 77, 123, 0.16), transparent 32%),
    rgba(95, 0, 103, 0.18);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.08),
    0 22px 70px rgba(95, 0, 103, 0.24);
  transform: translateY(-1px);
}

.attachment-drop-icon {
  display: grid;
  place-items: center;
  width: 74px;
  height: 74px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.06);
  color: #d8d2dc;
}

.attachment-picker-empty strong {
  color: #f4f1f5;
  font-size: clamp(20px, 2vw, 28px);
  font-weight: 950;
  letter-spacing: 0;
}

.attachment-picker-empty p,
.attachment-picker-empty small {
  margin: 0;
  color: #88828b;
  font-size: 16px;
  line-height: 1.4;
}

.attachment-picker-empty small {
  color: #665d6a;
  font-size: 13px;
  font-weight: 850;
}

.attachment-picker-empty b {
  color: #cfc9d1;
}

.attachment-picker-saved-empty {
  grid-column: 1 / -1;
  display: grid;
  place-items: center;
  gap: 6px;
  min-height: 150px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.018);
  color: #8d8492;
  text-align: center;
}

.attachment-picker-saved-empty b {
  color: #d8d2dc;
  font-size: 16px;
}

.attachment-picker-saved-empty span {
  font-size: 13px;
}

@media (max-width: 720px) {
