/* Pokaya AI brand refresh */
:root {
  color-scheme: light;
  --bg: #fff8fb;
  --panel: #ffffff;
  --panel-2: #fff0f6;
  --cream: #ffffff;
  --ink: #2b0634;
  --muted: #7a607f;
  --line: rgba(95, 0, 103, 0.12);
  --soft-line: #f0d8ed;
  --gold: #ff5a6f;
  --gold-2: #ff8b64;
  --brown: #fff0f7;
  --success: #23c980;
  --danger: #ff4f65;
  --purple: #5d086c;
  --purple-2: #8f148c;
  --pink: #ff4e78;
  --coral: #ff835e;
  --peach: #fff1e9;
  --shadow: 0 22px 58px rgba(76, 0, 87, 0.13);
}

body {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.95), rgba(255, 241, 247, 0.94)),
    repeating-linear-gradient(45deg, rgba(96, 8, 116, 0.03) 0 1px, transparent 1px 18px);
  color: var(--ink);
}

.loading,
.login-shell,
.public-shell,
.studio-shell,
.workspace,
.affiliate-shell {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(255, 241, 247, 0.96)),
    repeating-linear-gradient(45deg, rgba(94, 8, 108, 0.035) 0 1px, transparent 1px 22px);
  color: var(--ink);
}

.public-shell {
  min-height: 100vh;
}

.promo-bar {
  margin-bottom: 8px;
  border-radius: 0 0 8px 8px;
  background: linear-gradient(90deg, var(--pink), var(--coral));
  color: white;
  box-shadow: 0 14px 38px rgba(255, 79, 101, 0.22);
}

.public-nav {
  position: sticky;
  top: 0;
  z-index: 20;
  border-bottom: 1px solid rgba(93, 8, 108, 0.08);
  background: rgba(255, 255, 255, 0.84);
  backdrop-filter: blur(18px);
}

.brand-lockup {
  gap: 12px;
}

.brand-logo {
  width: 178px;
  height: 54px;
  object-fit: contain;
  object-position: left center;
  display: block;
  filter: drop-shadow(0 10px 18px rgba(92, 0, 103, 0.13));
}

.sidebar .brand-logo,
.login-card .brand-logo {
  width: 196px;
  height: 62px;
}

.brand-lockup b {
  color: var(--purple);
  letter-spacing: 0.08em;
}

.brand-lockup strong {
  color: var(--pink);
  font-size: 15px;
  font-weight: 950;
  letter-spacing: 0.04em;
}

.logo-mark {
  background: linear-gradient(135deg, var(--purple), var(--pink) 55%, var(--coral));
  color: white;
  box-shadow: 0 16px 34px rgba(255, 79, 101, 0.22);
}

.public-links a,
.public-footer,
.public-footer a,
.public-copy,
.public-grid p,
.pain-list p,
.feature-mosaic p,
.comparison-section p,
.testimonial-section p,
.pricing-section p,
.signup-section p,
.faq-section p,
.checkout-steps p,
.demo-reel p {
  color: var(--muted);
}

.public-links a:hover,
.text-button,
.eyebrow,
.folder-label,
.public-grid span,
.feature-mosaic span,
.compare-grid span,
.price-card > span,
.demo-reel span {
  color: var(--pink);
}

.public-hero {
  grid-template-columns: minmax(0, 1.08fr) minmax(340px, 0.92fr);
}

.public-hero h1,
.split-section h2,
.feature-section h2,
.comparison-section h2,
.testimonial-section h2,
.pricing-section h2,
.signup-section h2,
.faq-section h2,
.register-hero h1,
.affiliate-hero h1,
.project-head h1 {
  color: var(--purple);
  letter-spacing: 0;
}

.public-hero h1 {
  max-width: 820px;
}

.hero-board,
.public-grid article,
.pain-list article,
.feature-mosaic article,
.compare-grid article,
.quote-grid article,
.price-card,
.lead-form,
.faq-section details,
.checkout-steps article,
.demo-reel article,
.generator-box,
.upload-card,
.prompt-block,
.result-grid article,
.empty-result,
.schedule-list article,
.metric-row article,
.table div,
.topup-grid button,
.sop-sheet,
.login-card,
.modal,
.canvas-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: var(--shadow);
}

.hero-board {
  position: relative;
  overflow: hidden;
  padding: 28px;
}

.hero-logo {
  width: min(100%, 440px);
  margin: 4px auto 14px;
  display: block;
}

.race-card {
  border: 1px solid rgba(93, 8, 108, 0.1);
  background: #fff7fb;
  color: var(--purple);
}

.race-card.hot {
  color: var(--pink);
  background: linear-gradient(135deg, #fff3f0, #fff7fb);
}

.race-meter {
  background: #f5e2f1;
}

.race-meter i {
  background: linear-gradient(90deg, var(--purple), var(--pink), var(--coral));
}

.trust-row span,
.commission-orbit i {
  border-color: rgba(93, 8, 108, 0.12);
  background: white;
  color: var(--purple);
}

.gold-button,
.sop-button,
.checkout-steps b,
.chat-panel button,
.step-tabs button.active {
  background: linear-gradient(135deg, var(--pink), var(--coral));
  color: white;
  border-color: transparent;
  box-shadow: 0 16px 34px rgba(255, 79, 101, 0.24);
}

.dark-button,
.result-grid button,
.table button,
.schedule-list button,
.icon-only.close {
  background: var(--purple);
  color: white;
  border-color: transparent;
}

.dark-button:hover,
.gold-button:hover,
.side-link:hover,
.project-button:hover,
.topup-grid button:hover {
  transform: translateY(-1px);
}

.compare-grid .winner {
  border-color: rgba(255, 79, 101, 0.35);
  background: linear-gradient(135deg, #fff5f2, #fff8fc);
}

.compare-grid ul,
.price-card ul {
  color: var(--ink);
}

.price b,
.topup-grid b {
  color: var(--pink);
}

.demo-screen {
  background:
    linear-gradient(135deg, rgba(93, 8, 108, 0.92), rgba(255, 78, 120, 0.88), rgba(255, 131, 94, 0.9));
  color: white;
}

.commission-orbit {
  border-color: rgba(255, 79, 101, 0.32);
  background: linear-gradient(135deg, #fff, #fff1f7);
  box-shadow: 0 24px 60px rgba(255, 79, 101, 0.18);
}

.commission-orbit b {
  color: var(--pink);
}

.commission-orbit span {
  color: var(--purple);
}

.sidebar {
  border-right: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(255, 241, 247, 0.96));
}

.sidebar .brand-lockup {
  border-bottom: 1px solid var(--line);
}

.side-primary,
.new-project,
.side-link,
.project-button,
.step-tabs button {
  color: var(--muted);
  border-color: transparent;
  background: transparent;
}

.side-primary {
  border-color: rgba(93, 8, 108, 0.11);
  background: white;
  color: var(--purple);
}

.side-primary.active,
.side-link.active,
.project-button.active {
  color: var(--purple);
  background: #fff0f7;
  border-color: rgba(255, 79, 101, 0.18);
}

.new-project {
  color: white;
  border-color: transparent;
  background: linear-gradient(135deg, var(--purple), var(--pink));
  box-shadow: 0 16px 32px rgba(93, 8, 108, 0.16);
}

.new-project b {
  color: rgba(255, 255, 255, 0.76);
}

.search-box {
  color: var(--muted);
}

.search-box input,
input,
select,
textarea {
  border-color: var(--soft-line);
  background: #fff;
  color: var(--ink);
}

.project-button svg {
  border-color: rgba(93, 8, 108, 0.12);
  background: white;
}

.project-button.active svg {
  border-color: transparent;
  background: linear-gradient(135deg, var(--pink), var(--coral));
  color: white;
}

.canvas-card {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(255, 247, 252, 0.98));
  color: var(--ink);
}

.generator-box {
  border-color: rgba(255, 79, 101, 0.24);
  background: linear-gradient(135deg, #fff, #fff4f8);
}

.generator-box h2,
.upload-card h2,
.modal h2 {
  color: var(--purple);
}

label {
  color: #8a628f;
}

.drop-zone {
  border-color: rgba(255, 79, 101, 0.28);
  background: linear-gradient(135deg, #fff8fb, #fff1ec);
  color: var(--muted);
}

.drop-zone strong {
  color: var(--purple);
}

.drop-zone small,
.metric-row span,
.table small,
.schedule-list small,
.subtitle,
.empty-text {
  color: var(--muted);
}

.topup-grid button {
  background: linear-gradient(135deg, #fff, #fff5f9);
  color: var(--purple);
}

.chat-bubble {
  border-color: rgba(255, 255, 255, 0.8);
  background: linear-gradient(135deg, var(--purple), var(--pink), var(--coral));
  color: white;
  box-shadow: 0 18px 46px rgba(255, 79, 101, 0.32);
}

.live-panel,
.chat-panel,
.toast {
  border-color: var(--line);
  background: white;
  color: var(--ink);
}

.live-panel p {
  color: var(--muted);
}

.modal-backdrop {
  background: rgba(43, 6, 52, 0.38);
  backdrop-filter: blur(8px);
}

.toast {
  color: var(--purple);
}

.sop-center-head {
  align-items: end;
}

.sop-quick-grid {
  width: min(1480px, 100%);
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
  margin: 0 auto 18px;
}

.sop-quick-grid button {
  min-height: 132px;
  display: grid;
  align-content: start;
  gap: 10px;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 18px;
  padding: 17px;
  background: rgba(255, 255, 255, 0.86);
  color: var(--purple);
  text-align: left;
  box-shadow: 0 16px 36px rgba(93, 8, 108, 0.08);
}

.sop-quick-grid button.active {
  border-color: rgba(255, 63, 110, 0.34);
  background: linear-gradient(180deg, #fff0f5, #fff);
  box-shadow: inset 0 0 0 1px rgba(255, 63, 110, 0.12), 0 18px 42px rgba(255, 63, 110, 0.14);
}

.sop-quick-grid svg {
  color: var(--pink);
}

.sop-quick-grid span {
  font-size: 17px;
  font-weight: 950;
  line-height: 1.08;
}

.sop-quick-grid small {
  color: rgba(93, 8, 108, 0.66);
  font-size: 13px;
  font-weight: 760;
  line-height: 1.35;
}

.sop-center-layout {
  width: min(1480px, 100%);
  display: grid;
  grid-template-columns: minmax(250px, 320px) minmax(0, 1fr);
  gap: 18px;
  margin: 0 auto;
  align-items: start;
}

.sop-center-nav {
  position: sticky;
  top: 22px;
  display: grid;
  gap: 16px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 22px;
  padding: 16px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 18px 44px rgba(93, 8, 108, 0.08);
}

.sop-center-nav h3 {
  margin: 0 0 8px;
  color: rgba(93, 8, 108, 0.62);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.sop-center-nav button {
  width: 100%;
  min-height: 58px;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  border: 0;
  border-radius: 14px;
  padding: 10px 12px;
  background: transparent;
  color: rgba(31, 6, 38, 0.82);
  text-align: left;
}

.sop-center-nav button.active {
  background: linear-gradient(90deg, rgba(255, 63, 110, 0.18), rgba(244, 202, 50, 0.12));
  color: var(--purple);
}

.sop-center-nav button svg {
  color: var(--pink);
}

.sop-center-nav button span {
  display: grid;
  gap: 4px;
}

.sop-center-nav b {
  overflow: hidden;
  font-size: 14px;
  font-weight: 950;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sop-center-nav small {
  color: rgba(93, 8, 108, 0.52);
  font-size: 11px;
  font-weight: 850;
}

.sop-center-content {
  display: grid;
  gap: 18px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 26px;
  padding: clamp(22px, 3vw, 42px);
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 22px 60px rgba(93, 8, 108, 0.09);
}

.sop-center-title {
  display: grid;
  gap: 8px;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(93, 8, 108, 0.1);
}

.sop-center-title p,
.sop-center-title h2 {
  margin: 0;
}

.sop-center-title p {
  color: var(--pink);
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.sop-center-title h2 {
  color: var(--purple);
  font-size: clamp(30px, 3vw, 48px);
  line-height: 1;
}

.sop-center-title span {
  color: rgba(93, 8, 108, 0.62);
  font-size: 14px;
  font-weight: 850;
}

.sop-center-content .sop-copy-block,
.sop-center-content .sop-callout,
.sop-center-content .sop-workflow {
  margin: 0;
}

.sop-center-content .sop-copy-block {
  border: 1px solid rgba(93, 8, 108, 0.08);
  border-radius: 18px;
  padding: 20px;
  background: #fffaf2;
}

.sop-center-content .sop-copy-block h3,
.sop-center-content .sop-callout h3,
.sop-center-content .sop-workflow h3 {
  color: var(--purple);
}

.sop-center-content .sop-copy-block p,
.sop-center-content .sop-callout p,
.sop-center-content .sop-workflow p,
.sop-center-content .sop-step-body p,
.sop-center-content .sop-step-body li {
  color: rgba(31, 6, 38, 0.78);
  font-size: 16px;
  line-height: 1.55;
}

.sop-center-content .sop-step-card {
  background: #fff;
}

@media (max-width: 1180px) {
  .sop-quick-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .sop-center-layout {
    grid-template-columns: 1fr;
  }

  .sop-center-nav {
    position: static;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .agent-history-panel header,
  .agent-history-list article {
    align-items: stretch;
  }

  .agent-history-list article {
    grid-template-columns: minmax(0, 1fr);
  }

  .agent-history-actions {
    justify-content: flex-end;
  }

  .agent-history-compact {
    grid-template-columns: 20px minmax(0, 1fr) auto;
  }

  .agent-history-compact small {
    grid-column: 2 / -1;
    white-space: normal;
  }

  .sop-quick-grid,
  .sop-center-nav {
    display: flex;
    overflow-x: auto;
    padding-bottom: 6px;
  }

  .sop-quick-grid button {
    min-width: 240px;
  }

  .sop-center-nav > div {
    min-width: 260px;
  }

  .sop-center-content {
    padding: 18px;
  }
}

.sop-compact-head {
  min-height: 0;
  margin-bottom: 14px;
  align-items: center;
}

.sop-compact-head h1 {
  font-size: clamp(34px, 3.2vw, 48px);
  line-height: 0.96;
}

.sop-compact-head .subtitle {
  max-width: 620px;
}

.sop-compact-head .head-actions {
  gap: 8px;
}

.sop-command-bar {
  width: min(1480px, 100%);
  display: grid;
  grid-template-columns: minmax(300px, 0.62fr) minmax(360px, 1fr);
  gap: 12px;
  align-items: center;
  margin: 0 auto 14px;
}

.sop-command-bar label {
  min-height: 52px;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 14px;
  padding: 0 14px;
  background: rgba(255, 255, 255, 0.92);
  color: var(--pink);
  box-shadow: 0 12px 30px rgba(93, 8, 108, 0.06);
}

.sop-command-bar input {
  min-height: 50px;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--purple);
  font-weight: 850;
}

.sop-path-pills {
  min-height: 52px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 14px;
  padding: 8px;
  background: rgba(255, 255, 255, 0.74);
}

.sop-path-pills span {
  color: rgba(93, 8, 108, 0.54);
  font-size: 12px;
  font-weight: 950;
  text-transform: uppercase;
}

.sop-path-pills button {
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 999px;
  padding: 9px 13px;
  background: #fff;
  color: var(--purple);
  font-size: 13px;
  font-weight: 950;
  white-space: nowrap;
}

.sop-path-pills button.active {
  border-color: rgba(255, 63, 110, 0.34);
  background: #fff0f5;
  color: var(--pink);
}

.sop-search-results {
  width: min(1480px, 100%);
  display: grid;
  gap: 8px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 16px;
  padding: 14px;
  margin: 0 auto 14px;
  background: rgba(255, 255, 255, 0.9);
}

.sop-search-results button {
  display: grid;
  gap: 4px;
  border: 1px solid rgba(93, 8, 108, 0.08);
  border-radius: 12px;
  padding: 12px 14px;
  background: #fff;
  color: var(--purple);
  text-align: left;
}

.sop-search-results span {
  color: var(--purple);
  font-weight: 950;
}

.sop-search-results small {
  color: rgba(31, 6, 38, 0.64);
  font-size: 13px;
  line-height: 1.35;
}

.sop-quick-grid {
  gap: 10px;
  margin-bottom: 16px;
}

.sop-quick-grid button {
  min-height: 104px;
  border-radius: 12px;
  gap: 7px;
  padding: 13px 14px;
}

.sop-quick-grid span {
  font-size: 18px;
  line-height: 1;
}

.sop-quick-grid small {
  min-height: 36px;
  font-size: 12px;
  line-height: 1.3;
}

.sop-quick-grid em {
  color: rgba(93, 8, 108, 0.48);
  font-size: 11px;
  font-style: normal;
  font-weight: 950;
  text-transform: uppercase;
}

.sop-center-layout {
  grid-template-columns: minmax(230px, 290px) minmax(0, 1fr);
  gap: 14px;
}

.sop-center-nav {
  top: 14px;
  gap: 12px;
  border-radius: 16px;
  padding: 12px;
}

.sop-center-nav button {
  min-height: 46px;
  border-radius: 10px;
  padding: 8px 10px;
}

.sop-center-nav b {
  font-size: 13px;
}

.sop-center-content {
  gap: 14px;
  border-radius: 18px;
  padding: clamp(18px, 2.4vw, 30px);
}

.sop-center-title {
  gap: 7px;
  padding-bottom: 14px;
}

.sop-center-title h2 {
  max-width: 980px;
  font-size: clamp(28px, 2.6vw, 38px);
  line-height: 1.02;
}

.sop-info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.sop-center-content .sop-copy-block,
.sop-center-content .sop-callout,
.sop-center-content .sop-workflow,
.sop-center-content .sop-checklist {
  border-radius: 12px;
  padding: 16px;
}

.sop-center-content .sop-copy-block h3,
.sop-center-content .sop-callout h3,
.sop-center-content .sop-workflow h3,
.sop-center-content .sop-checklist h3 {
  margin-top: 0;
  font-size: 15px;
}

.sop-center-content .sop-copy-block p,
.sop-center-content .sop-callout p,
.sop-center-content .sop-workflow p,
.sop-center-content .sop-step-body p,
.sop-center-content .sop-step-body li {
  font-size: 15px;
  line-height: 1.48;
}

.sop-center-content .sop-step-card {
  border-radius: 12px;
}

.sop-center-content .sop-step-title {
  padding: 14px 16px;
}

.sop-center-content .sop-step-title h4 {
  font-size: 16px;
}

.sop-center-content .sop-step-body {
  padding: 14px 16px 16px 56px;
}

.sop-checklist {
  display: grid;
  gap: 10px;
  border: 1px solid rgba(93, 8, 108, 0.08);
  background: #fff;
}

.sop-checklist label {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(31, 6, 38, 0.78);
  font-size: 14px;
  font-weight: 850;
}

.sop-checklist input {
  width: 18px;
  height: 18px;
  accent-color: var(--pink);
}

.sop-next-panel {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  border: 1px solid rgba(255, 63, 110, 0.18);
  border-radius: 14px;
  padding: 14px 16px;
  background: linear-gradient(90deg, #fff6f0, #fff);
}

.sop-next-panel span {
  display: block;
  color: rgba(93, 8, 108, 0.54);
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.sop-next-panel b {
  color: var(--purple);
}

@media (max-width: 1180px) {
  .sop-command-bar,
  .sop-info-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 680px) {
  .sop-compact-head {
    align-items: stretch;
  }

  .sop-compact-head .head-actions {
    width: 100%;
  }

  .sop-command-bar {
    gap: 8px;
  }

  .sop-quick-grid button {
    min-width: 190px;
    min-height: 92px;
  }

  .sop-center-content .sop-step-body {
    padding: 14px;
  }

  .sop-next-panel {
    align-items: stretch;
    flex-direction: column;
  }
}

/* Admin CRM operator console overrides. */
.studio-shell .admin-health-strip {
  grid-template-columns: repeat(6, minmax(0, 1fr)) !important;
  gap: 10px !important;
  margin-bottom: 16px !important;
}

.studio-shell .admin-health-strip button,
.studio-shell .admin-action-item,
.studio-shell .admin-diagnostics-toggle {
  min-height: 0 !important;
  border-radius: 10px !important;
}

.studio-shell .admin-health-strip button {
  min-height: 82px !important;
  padding: 12px !important;
