}

.studio-shell .admin-profile-metrics {
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
}

.studio-shell .admin-diagnostics-body {
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
}

@media (max-width: 1180px) {
  .studio-shell .admin-health-strip,
  .studio-shell .admin-action-grid,
  .studio-shell .admin-diagnostics-body {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .studio-shell .admin-crm-layout {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 760px) {
  .studio-shell .admin-health-strip,
  .studio-shell .admin-action-grid,
  .studio-shell .admin-crm-toolbar,
  .studio-shell .admin-diagnostics-body {
    grid-template-columns: 1fr !important;
  }

  .studio-shell .admin-user-row,
  .studio-shell .admin-user-row.head {
    grid-template-columns: 1fr 1fr !important;
  }
}

.sop-backdrop {
  padding: clamp(10px, 2vw, 24px);
  background: rgba(16, 3, 20, 0.7);
  backdrop-filter: blur(10px);
}

.sop-modal {
  width: min(1120px, 58vw);
  height: min(90vh, 980px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 22px;
  background: #08060a;
  color: #fff;
  box-shadow: 0 32px 100px rgba(20, 2, 26, 0.54);
}

.sop-modal-head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  min-height: 104px;
  padding: 18px 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  background:
    radial-gradient(circle at 6% 18%, rgba(255, 78, 120, 0.2), transparent 24%),
    linear-gradient(135deg, #19091e, #10080f 58%, #1c0a14);
}

.sop-modal-icon {
  width: 56px;
  height: 56px;
  display: inline-grid;
  place-items: center;
  border-radius: 16px;
  background: linear-gradient(135deg, var(--pink), var(--coral));
  color: #fff;
  box-shadow: 0 18px 42px rgba(255, 78, 120, 0.28);
}

.sop-modal-head p,
.sop-copy-block h3,
.sop-callout h3,
.sop-checklist h3 {
  margin: 0;
  color: var(--pink);
  font-weight: 950;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.sop-modal-head h2 {
  margin: 5px 0 0;
  color: #fff;
  font-size: clamp(22px, 1.65vw, 30px);
  line-height: 1.06;
}

.sop-close {
  width: 46px;
  min-height: 46px;
  border: 0;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.07);
  color: rgba(255, 255, 255, 0.76);
}

.sop-close:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
}

.sop-modal-scroll {
  overflow-y: auto;
  padding: 32px 48px 38px;
  scrollbar-color: rgba(255, 255, 255, 0.42) transparent;
}

.sop-path {
  margin: 0 0 26px;
  color: rgba(255, 255, 255, 0.38);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: clamp(14px, 1vw, 18px);
  font-weight: 850;
  letter-spacing: 0.04em;
}

.sop-copy-block p {
  max-width: 1320px;
  margin: 16px 0 28px;
  color: rgba(255, 255, 255, 0.92);
  font-size: clamp(15px, 1.05vw, 19px);
  line-height: 1.55;
}

.sop-callout {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 20px;
  align-items: start;
  margin-bottom: 32px;
  padding: 20px 28px;
  border: 1px solid rgba(255, 78, 120, 0.36);
  border-radius: 22px;
  background:
    linear-gradient(135deg, rgba(255, 78, 120, 0.11), rgba(255, 131, 94, 0.07)),
    rgba(255, 255, 255, 0.03);
}

.sop-callout > svg,
.sop-guide > h3 svg {
  color: var(--pink);
  stroke-width: 3;
}

.sop-callout p {
  margin: 12px 0 0;
  color: rgba(255, 255, 255, 0.86);
  font-size: clamp(15px, 0.95vw, 18px);
  line-height: 1.48;
}

.sop-guide > h3 {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 20px;
  color: #fff;
  font-size: clamp(18px, 1.25vw, 23px);
}

.sop-section-heading {
  margin: 8px 0 0;
  color: var(--pink);
  font-size: 15px;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.sop-step-list {
  display: grid;
  gap: 18px;
}

.sop-step-card {
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 18px;
  background: #161417;
}

.sop-step-title {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 28px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sop-step-title span {
  width: 44px;
  height: 44px;
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 14px;
  background: linear-gradient(135deg, var(--pink), var(--coral));
  color: #fff;
  font-size: 20px;
  font-weight: 950;
}

.sop-step-title h4 {
  margin: 0;
  color: #fff;
  font-size: clamp(17px, 1.05vw, 21px);
}

.sop-step-body {
  display: grid;
  gap: 10px;
  padding: 18px 28px 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background:
    linear-gradient(135deg, rgba(255, 78, 120, 0.05), rgba(255, 131, 94, 0.025)),
    #0d0b0f;
}

.sop-step-body strong {
  color: rgba(255, 255, 255, 0.92);
  font-size: 15px;
  line-height: 1.45;
}

.sop-step-body p {
  margin: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: 14px;
  line-height: 1.55;
}

.sop-step-body ul {
  display: grid;
  gap: 7px;
  margin: 0;
  padding-left: 20px;
  color: rgba(255, 255, 255, 0.76);
  font-size: 14px;
  line-height: 1.5;
}

.sop-step-body li::marker {
  color: var(--pink);
}

.sop-tip {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  margin-top: 4px;
  padding: 13px 16px;
  border: 1px solid rgba(255, 78, 120, 0.24);
  border-radius: 16px;
  background: rgba(255, 78, 120, 0.08);
}

.sop-tip svg {
  color: var(--pink);
  stroke-width: 3;
}

.sop-tip b {
  display: block;
  margin-bottom: 4px;
  color: var(--pink);
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.sop-tip p {
  color: rgba(255, 255, 255, 0.78);
}

.sop-step-preview {
  min-height: 190px;
  display: grid;
  grid-template-columns: minmax(150px, 0.24fr) minmax(0, 1fr);
  background: #09080a;
}

.sop-mini-sidebar {
  display: grid;
  align-content: start;
  gap: 12px;
  padding: 22px;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
  background: linear-gradient(180deg, #1b0a20, #0e080f);
}

.sop-mini-sidebar b {
  color: var(--pink);
  font-size: 12px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.sop-mini-sidebar i,
.sop-mini-grid i {
  display: block;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.1);
}

.sop-mini-sidebar i {
  height: 22px;
}

.sop-mini-screen {
  display: grid;
  align-content: start;
  gap: 16px;
  padding: 24px;
}

.sop-mini-screen strong {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--pink);
  font-size: 15px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.sop-mini-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.sop-mini-grid i {
  height: 58px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background:
    linear-gradient(135deg, rgba(255, 78, 120, 0.16), rgba(255, 131, 94, 0.08)),
    rgba(255, 255, 255, 0.06);
}

.sop-mini-screen p {
  max-width: 900px;
  margin: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: 16px;
  line-height: 1.55;
}

.sop-checklist {
  margin-top: 26px;
  padding: 24px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.05);
}

.sop-workflow {
  margin-top: 24px;
  padding: 20px 24px;
  border: 1px solid rgba(255, 78, 120, 0.28);
  border-radius: 20px;
  background:
    linear-gradient(135deg, rgba(255, 78, 120, 0.1), rgba(255, 131, 94, 0.06)),
    rgba(255, 255, 255, 0.03);
}

.sop-workflow h3 {
  margin: 0 0 10px;
  color: var(--pink);
  font-weight: 950;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.sop-workflow p {
  margin: 0;
  color: rgba(255, 255, 255, 0.82);
  font-size: 14px;
  line-height: 1.55;
}

.sop-checklist div {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 18px;
}

.sop-checklist span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.82);
  font-weight: 850;
}

.sop-checklist svg {
  color: var(--success);
}

.sop-modal-foot {
  display: flex;
  justify-content: flex-end;
  padding: 16px 48px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(6, 5, 7, 0.96);
}

.sop-understood {
  min-width: 220px;
  min-height: 54px;
  border: 0;
  border-radius: 14px;
  background: linear-gradient(135deg, var(--pink), var(--coral));
  color: #fff;
  font-size: 18px;
  font-weight: 950;
  box-shadow: 0 20px 54px rgba(255, 78, 120, 0.34);
}

@media (max-width: 760px) {
  .sop-modal {
    width: calc(100vw - 20px);
    height: calc(100vh - 20px);
    border-radius: 20px;
  }

  .sop-modal-head,
  .sop-modal-scroll,
  .sop-modal-foot {
    padding-inline: 20px;
  }

  .sop-modal-head {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 14px;
    min-height: 112px;
  }

  .sop-modal-icon {
    width: 54px;
    height: 54px;
    border-radius: 16px;
  }

  .sop-modal-head h2 {
    font-size: 24px;
  }

  .sop-close {
    width: 44px;
    min-height: 44px;
  }

  .sop-copy-block p {
    font-size: 20px;
  }

  .sop-callout,
  .sop-step-preview {
    grid-template-columns: 1fr;
  }

  .sop-mini-sidebar {
    display: none;
  }

  .sop-mini-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sop-understood {
    width: 100%;
    min-width: 0;
    font-size: 22px;
  }
}

@media (max-width: 1100px) {
  .brand-logo {
    width: 144px;
    height: 50px;
  }

  .step-tabs button {
    justify-content: flex-start;
  }

  .public-hero h1 {
    font-size: clamp(40px, 11vw, 64px);
  }
}

/* PRD hero conversion: Pokaya AI branded, not competitor-skinned */
.public-shell {
  padding-bottom: 72px;
}

.promo-bar,
.public-nav,
.public-hero {
  width: min(1440px, 100%);
}

.public-nav {
  max-width: 1440px;
}

.public-hero {
  position: relative;
  min-height: calc(100vh - 154px);
  grid-template-columns: minmax(0, 0.9fr) minmax(520px, 0.94fr);
  gap: clamp(30px, 4vw, 70px);
  padding: clamp(34px, 4vw, 58px);
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 28px;
  overflow: hidden;
  background:
    linear-gradient(rgba(93, 8, 108, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(93, 8, 108, 0.035) 1px, transparent 1px),
    radial-gradient(circle at 78% 18%, rgba(255, 78, 120, 0.14), transparent 27%),
    radial-gradient(circle at 18% 80%, rgba(255, 131, 94, 0.12), transparent 26%),
    linear-gradient(135deg, #fff, #fff7fb 56%, #fff1e9);
  background-size:
    42px 42px,
    42px 42px,
    auto,
    auto,
    auto;
  box-shadow: 0 34px 90px rgba(76, 0, 87, 0.13);
}

.public-hero::before {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.2));
  content: "";
}

.public-hero > * {
  position: relative;
  z-index: 1;
}

.public-hero .eyebrow {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  margin-bottom: 22px;
  border: 1px solid rgba(35, 201, 128, 0.22);
  border-radius: 999px;
  padding: 10px 18px;
  background: #ecfff6;
  color: #188b58;
  box-shadow: 0 14px 34px rgba(35, 201, 128, 0.13);
}

.public-hero h1.hero-headline {
  max-width: 780px;
  display: grid;
  gap: 0;
  margin-bottom: 24px;
  color: var(--purple);
  font-size: clamp(48px, 4.35vw, 78px);
  line-height: 0.94;
  letter-spacing: 0;
}

.hero-headline span,
.hero-headline mark {
  display: block;
}

.hero-headline mark {
  padding: 0;
  background: transparent;
  color: var(--pink);
}

.public-hero .public-copy {
  max-width: 720px;
  color: var(--muted);
  font-size: clamp(18px, 1.5vw, 24px);
  line-height: 1.5;
}

.public-hero .public-copy::first-line {
  color: var(--purple);
  font-weight: 950;
}

.public-hero .public-actions {
  margin-top: 28px;
}

.public-hero .gold-button {
  min-height: 60px;
  border-radius: 12px;
  padding: 17px 30px;
  background: linear-gradient(135deg, var(--pink), var(--coral));
  color: white;
  box-shadow: 0 22px 50px rgba(255, 79, 101, 0.26);
  font-size: 18px;
}

.public-hero .demo-button {
  min-height: 60px;
  border: 1px solid rgba(93, 8, 108, 0.13);
  border-radius: 12px;
  padding: 17px 26px;
  background: rgba(93, 8, 108, 0.95);
  color: white;
  text-decoration: none;
}

.public-hero .trust-row {
  align-items: center;
  margin-top: 28px;
  color: var(--muted);
}

.public-hero .trust-row span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
}

.public-hero .trust-row svg {
  color: var(--pink);
  fill: currentColor;
}

.public-hero .trust-row span:nth-child(3) svg {
  color: #ff4f65;
}

.avatar-stack {
  display: inline-flex !important;
  min-width: 112px;
}

.avatar-stack i {
  width: 34px;
  height: 34px;
  margin-right: -10px;
  border: 2px solid white;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--purple), #8b5cf6);
}

.avatar-stack i:nth-child(2) {
  background: linear-gradient(135deg, #8b5cf6, var(--pink));
}

.avatar-stack i:nth-child(3) {
  background: linear-gradient(135deg, var(--pink), var(--coral));
}

.avatar-stack i:nth-child(4) {
  background: linear-gradient(135deg, var(--coral), #25d0a1);
}

.hero-board {
  min-height: 650px;
  display: grid;
  align-content: start;
  gap: 18px;
  padding: 20px;
  border: 1px solid rgba(93, 8, 108, 0.13);
  border-radius: 20px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(255, 242, 248, 0.96)),
    repeating-linear-gradient(45deg, rgba(93, 8, 108, 0.04) 0 1px, transparent 1px 18px);
  box-shadow: 0 26px 70px rgba(76, 0, 87, 0.16);
}

.hero-board::after {
  position: absolute;
  inset: auto 0 0;
  height: 34%;
  pointer-events: none;
  background: linear-gradient(0deg, rgba(255, 78, 120, 0.1), transparent);
  content: "";
}

.hero-scene {
  position: relative;
  z-index: 1;
  width: 100%;
  height: clamp(380px, 36vw, 520px);
  display: block;
  object-fit: cover;
  object-position: 38% center;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 16px;
  box-shadow: 0 18px 42px rgba(76, 0, 87, 0.12);
}

.hero-board-panel {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(220px, 0.95fr);
  gap: 12px;
}

.product-link-card,
.output-stack article {
  position: relative;
  z-index: 1;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 14px 30px rgba(76, 0, 87, 0.08);
}

.product-link-card {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.product-link-card span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--pink);
  font-weight: 950;
}

.product-link-card b {
  color: var(--purple);
  font-size: clamp(18px, 1.25vw, 22px);
}

.output-stack {
  position: relative;
  z-index: 1;
  display: grid;
  grid-column: 1;
  gap: 10px;
}

.output-stack article {
  display: grid;
  grid-template-columns: 34px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 13px 15px;
}

.output-stack svg {
  color: var(--pink);
}

.output-stack b {
  color: var(--purple);
}

.output-stack span {
  border-radius: 999px;
  padding: 6px 10px;
  background: #ecfff6;
  color: #188b58;
  font-size: 12px;
  font-weight: 950;
  text-transform: uppercase;
}

.hero-board .race-card {
  position: relative;
  z-index: 1;
  width: 100%;
  align-self: start;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 15px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 12px;
  background: #fff7fb;
  color: var(--purple);
  box-shadow: none;
}

.hero-board .race-card.self {
  grid-column: 2;
  grid-row: 1;
  align-self: end;
}

.hero-board .race-card.hot {
  grid-column: 2;
  grid-row: 2;
}

.hero-board .race-card span {
  color: var(--purple);
  font-size: 15px;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: none;
}

.hero-board .race-card b {
  font-size: 18px;
}

.hero-board .race-card.hot {
  background: linear-gradient(135deg, #fff2f7, #fff3ef);
  color: var(--pink);
}

.hero-board .race-card.hot span {
  color: var(--pink);
}

.race-meter {
  position: relative;
  z-index: 1;
  grid-column: 2;
  grid-row: 3;
  align-self: start;
  height: 20px;
  overflow: hidden;
  border-radius: 999px;
  background: #f5e2f1;
}

.race-meter i {
  width: 79%;
  height: 100%;
  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--purple), var(--pink), var(--coral));
}

.catch-badge {
  position: relative;
  z-index: 1;
  grid-column: 1 / -1;
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  border: 1px solid rgba(255, 78, 120, 0.22);
  border-radius: 999px;
  padding: 11px 15px;
  background: white;
  color: var(--purple);
  box-shadow: 0 14px 30px rgba(76, 0, 87, 0.08);
}

.catch-badge svg {
  color: var(--pink);
  fill: currentColor;
}

/* Conversion PRD landing sections. */
.proof-strip,
.test-volume-section,
.output-preview-section,
.workflow-section,
.control-section,
.system-section,
.case-section,
.scenario-section,
.journey-section {
  width: min(1180px, 100%);
  margin: 0 auto;
}

.proof-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  padding: 24px 0 72px;
}

.proof-strip article {
  min-height: 84px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 14px;
  padding: 18px;
  background: rgba(255, 255, 255, 0.88);
  color: var(--purple);
  box-shadow: 0 16px 42px rgba(76, 0, 87, 0.08);
}

.proof-strip svg,
.split-section .pain-list svg,
.workflow-steps svg,
.control-grid svg {
  color: var(--pink);
}

.proof-strip b {
  font-size: 16px;
  line-height: 1.18;
}

.split-section .pain-list article {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(93, 8, 108, 0.12);
  background:
    radial-gradient(circle at 100% 0, rgba(255, 78, 120, 0.12), transparent 30%),
    white;
  color: var(--purple);
  box-shadow: 0 16px 42px rgba(76, 0, 87, 0.08);
}

.split-section .pain-list svg {
  margin-bottom: 16px;
}

.split-section .pain-list h3 {
  color: var(--purple);
}

.split-section .pain-list p {
  color: #77657d;
}

.output-preview-section,
.workflow-section,
.control-section,
.system-section,
.case-section,
.scenario-section,
.test-volume-section,
.journey-section {
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr);
  align-items: start;
  gap: clamp(24px, 4vw, 56px);
  padding: 76px 0;
  border-top: 1px solid rgba(93, 8, 108, 0.12);
}

.output-preview-section h2,
.workflow-section h2,
.control-section h2,
.system-section h2,
.case-section h2,
.scenario-section h2,
.test-volume-section h2,
.journey-section h2 {
  max-width: 780px;
  margin-bottom: 18px;
  color: var(--purple);
  font-size: clamp(34px, 3.55vw, 56px);
  line-height: 1.04;
  letter-spacing: 0;
  overflow-wrap: normal;
  word-break: keep-all;
  text-wrap: balance;
}

.output-preview-section p,
.workflow-section p,
.control-section p,
.system-section p,
.case-section p,
.scenario-section p,
.test-volume-section p,
.journey-section p {
  color: #77657d;
  line-height: 1.55;
}

.output-preview-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.output-preview-grid article,
.workflow-steps article,
.control-grid article,
.system-grid article,
.case-card,
.scenario-grid article,
.volume-formula article,
.journey-grid article {
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 14px;
  background: white;
  box-shadow: 0 16px 42px rgba(76, 0, 87, 0.08);
}

.test-volume-section {
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  padding-top: 36px;
}

.volume-formula {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.volume-formula article {
  min-height: 220px;
  display: grid;
  align-content: start;
  gap: 12px;
  padding: 20px;
}

.volume-formula b {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--pink), var(--coral));
  color: #fff;
  font-size: 15px;
}

.volume-formula span {
  color: var(--purple);
  font-size: 20px;
  font-weight: 950;
  line-height: 1.12;
}

.volume-formula p {
  margin: 0;
  font-size: 14px;
}

.journey-section {
  grid-template-columns: minmax(0, 0.75fr) minmax(0, 1.25fr);
}

.journey-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
  gap: 12px;
}

.journey-grid article {
  min-height: 184px;
  display: grid;
  align-content: start;
  gap: 12px;
  padding: 20px;
}

.journey-grid span {
  width: fit-content;
  border-radius: 999px;
  padding: 7px 10px;
  background: rgba(255, 78, 120, 0.12);
  color: var(--pink);
  font-size: 12px;
  font-weight: 950;
}

.journey-grid h3 {
  margin: 0;
  color: var(--purple);
  font-size: 20px;
  line-height: 1.1;
}

.journey-grid p {
  margin: 0;
  font-size: 14px;
  line-height: 1.45;
}

.system-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.system-grid article {
  min-height: 220px;
  display: grid;
  align-content: start;
  gap: 14px;
  padding: 22px;
}

.system-grid svg,
.case-card span,
.scenario-grid svg {
  color: var(--pink);
}

.system-grid h3 {
  margin: 0;
  color: var(--purple);
  font-size: 24px;
  line-height: 1.1;
}

.case-section {
  grid-template-columns: minmax(0, 1fr) minmax(320px, 420px);
}

.case-card {
  display: grid;
  gap: 16px;
  padding: 28px;
  background:
    radial-gradient(circle at 88% 0, rgba(255, 78, 120, 0.14), transparent 34%),
    #fff;
}

.case-card > span {
  width: fit-content;
  border-radius: 999px;
  padding: 8px 11px;
  background: #fff2f7;
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.case-card b {
  color: var(--pink);
  font-size: clamp(54px, 7vw, 84px);
  line-height: 0.88;
}

.case-card ul {
  display: grid;
  gap: 10px;
  margin: 0;
  padding-left: 20px;
  color: var(--purple);
  font-weight: 850;
}

.scenario-section {
  grid-template-columns: minmax(0, 0.78fr) minmax(0, 1.22fr);
}

.scenario-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.scenario-grid article {
  min-height: 76px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px;
  color: var(--purple);
  font-weight: 950;
}

.output-preview-grid article {
  min-height: 210px;
  display: grid;
  align-content: start;
  gap: 14px;
  padding: 22px;
}

.output-preview-grid span,
.workflow-steps b {
  width: fit-content;
  border-radius: 999px;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 950;
}

.output-preview-grid span {
  background: #fff2f7;
  color: var(--pink);
}

.output-preview-grid h3,
.workflow-steps h3 {
  margin: 0;
  color: var(--purple);
  font-size: 24px;
  line-height: 1.1;
}

.workflow-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.workflow-steps article {
  min-height: 238px;
  display: grid;
  align-content: start;
  gap: 14px;
  padding: 22px;
}

.workflow-steps b {
  background: linear-gradient(135deg, var(--purple), var(--pink));
  color: white;
}

.demo-section .demo-reel {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.demo-section .demo-reel article {
  min-height: 330px;
  border-color: rgba(93, 8, 108, 0.12);
  background:
    linear-gradient(180deg, rgba(255, 78, 120, 0.03), rgba(93, 8, 108, 0.08)),
    white;
  color: var(--purple);
  box-shadow: 0 18px 42px rgba(76, 0, 87, 0.1);
}

.demo-section .demo-screen {
  min-height: 178px;
  position: relative;
  align-content: center;
  gap: 10px;
  background:
    radial-gradient(circle at 50% 26%, rgba(255, 78, 120, 0.32), transparent 38%),
    linear-gradient(160deg, #5d086c, #ff4e78 58%, #ff835e);
  color: white;
}

.demo-section .demo-screen small {
  position: absolute;
  right: 12px;
  bottom: 12px;
  border-radius: 999px;
  padding: 7px 10px;
  background: rgba(16, 7, 18, 0.58);
  color: #fff;
  font-size: 12px;
  font-weight: 950;
  backdrop-filter: blur(10px);
}

.demo-section .demo-reel p {
  color: #77657d;
  font-weight: 850;
}

.demo-section .demo-reel span {
  color: var(--pink);
}

.price-card .risk-note {
  margin-top: 14px;
  border-radius: 12px;
  padding: 12px 14px;
  background: #fff2f7;
  color: var(--purple);
  font-weight: 850;
}

.control-grid {
  display: grid;
  gap: 12px;
}

.control-grid article {
  display: grid;
  grid-template-columns: 30px 1fr;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
}

.control-grid p {
  margin: 0;
  color: var(--purple);
  font-weight: 850;
}

  @media (max-width: 1100px) {
  .dashboard-stat-grid,
  .date-filter-card,
  .dashboard-main-grid,
  .project-status {
    grid-template-columns: 1fr;
  }

  .head-actions {
    justify-content: flex-start;
