  }

  .hero-board,
  .hero-photo {
    min-height: auto;
  }

  .hero-scene {
    height: clamp(300px, 52vw, 440px);
  }

  .hero-board-panel {
    grid-template-columns: 1fr;
  }

  .output-stack,
  .hero-board .race-card.self,
  .hero-board .race-card.hot,
  .race-meter,
  .catch-badge {
    grid-column: auto;
    grid-row: auto;
