/* Reference-style login page */
.login-shell {
  min-height: 100vh;
  display: grid;
  align-content: start;
  justify-items: center;
  gap: clamp(16px, 2.8vh, 28px);
  padding: clamp(22px, 4vh, 34px) 16px 24px;
  background:
    radial-gradient(circle at 50% 12%, rgba(255, 78, 120, 0.22), transparent 24%),
    radial-gradient(circle at 78% 42%, rgba(93, 8, 108, 0.24), transparent 30%),
    linear-gradient(135deg, #130715, #080708 52%, #16090f);
  color: #f7f7f3;
}

.login-brand .brand-lockup {
  margin: 0;
}

.login-brand .brand-core {
  gap: 12px;
}

.login-brand .brand-logo-mascot {
  width: 60px;
  height: 60px;
  filter: drop-shadow(0 18px 34px rgba(255, 78, 120, 0.24));
}

.login-brand .brand-wordmark {
  color: #f7f7f3;
  font-size: clamp(32px, 4.8vw, 44px);
  letter-spacing: 0;
}

.login-brand .brand-wordmark span:last-child {
  color: var(--pink);
}

.login-card {
  width: min(680px, calc(100vw - 32px));
  display: grid;
  gap: clamp(18px, 2.6vw, 26px);
  padding: clamp(26px, 3.8vw, 38px);
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 26px;
  background: rgba(21, 18, 22, 0.94);
  box-shadow:
    0 34px 90px rgba(76, 0, 87, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.03);
