.login-card .brand-lockup {
  display: none;
}

.login-copy {
  display: grid;
  gap: 8px;
  text-align: left;
}

.login-card h1 {
  margin: 0;
  color: #f7f7f3;
  font-size: clamp(36px, 4.8vw, 48px);
  line-height: 1.02;
  letter-spacing: 0;
}

.login-copy > p {
