.google-login-button {
  width: 100%;
  min-height: 60px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  background: #f7f7f3;
  color: #21002e;
  font-size: 18px;
  font-weight: 950;
  box-shadow: 0 20px 48px rgba(255, 78, 120, 0.16);
