.google-login-button:hover {
  transform: translateY(-1px);
  border-color: rgba(255, 78, 120, 0.46);
  box-shadow: 0 24px 58px rgba(255, 78, 120, 0.22);
}

.google-mark {
  width: 30px;
  height: 30px;
