  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, #ffffff, #ffe9ef);
  color: var(--pink);
  font-size: 18px;
  font-weight: 950;
  box-shadow: inset 0 0 0 1px rgba(33, 0, 46, 0.08);
}

.login-divider {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 14px;
  color: rgba(247, 247, 243, 0.48);
  font-size: 13px;
  font-weight: 900;
  text-transform: uppercase;
}

.login-divider::before,
.login-divider::after {
  content: "";
  height: 1px;
  background: rgba(255, 255, 255, 0.1);
}

.login-form {
  display: grid;
  gap: 16px;
}

.login-form label {
  gap: 8px;
  color: #f2f2ee;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: none;
}

.login-form input {
  min-height: 58px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 14px 22px;
  background: #111012;
  color: #f7f7f3;
  font-size: 17px;
  font-weight: 650;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.22);
}

.login-form input::placeholder {
  color: #777;
}

.login-form input:focus {
  border-color: rgba(255, 78, 120, 0.72);
