  line-height: 1.45;
}

.agent-page-hero .dark-button {
  margin-top: 20px;
}

.agent-3d-card {
  position: relative;
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(320px, 1fr) auto;
  overflow: hidden;
  border: 1px solid rgba(93, 8, 108, 0.14);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(255, 247, 251, 0.92)),
    #fff;
  box-shadow: 0 20px 52px rgba(76, 0, 87, 0.12);
}

.agent-office-card {
  min-height: 430px;
  background: #fff;
}

.agent-render-card {
  width: 100%;
  min-height: 520px;
  background: #fff;
}

.agent-life-card {
  width: 100%;
  min-height: min(620px, calc(100vh - 300px));
  background: #fff;
}

.agent-life-stage {
  position: relative;
  z-index: 1;
  min-height: 370px;
  overflow: hidden;
  background: #fff;
}

.agent-life-render-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  opacity: 1;
  transition: opacity 220ms ease;
}

.agent-life-render-sleep {
  opacity: 0;
}

.agent-life-card[data-agent-phase="idle"] .agent-life-render-active,
.agent-life-card[data-agent-phase="wake"] .agent-life-render-active {
  opacity: 0;
}

.agent-life-card[data-agent-phase="idle"] .agent-life-render-sleep,
.agent-life-card[data-agent-phase="wake"] .agent-life-render-sleep {
  opacity: 1;
}

.agent-life-route {
  position: absolute;
  z-index: 2;
  left: 27%;
  right: 31%;
  bottom: 29%;
  height: 2px;
  border-radius: 99px;
  background: linear-gradient(90deg, transparent, rgba(93, 8, 108, 0.18), transparent);
  opacity: 0;
}

.agent-chair-mask {
  position: absolute;
  z-index: 3;
  left: 27%;
  bottom: 21.6%;
  width: 8.8%;
  height: 8.4%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.96) 0 45%, rgba(255, 255, 255, 0.56) 70%, transparent 100%);
  filter: blur(1px);
  opacity: 0;
  pointer-events: none;
}

.agent-life-card[data-agent-phase="working"] .agent-chair-mask,
.agent-life-card[data-agent-phase="done"]:not([data-agent-mode="chat"]) .agent-chair-mask {
  opacity: 1;
}

.agent-sprite {
  position: absolute;
  z-index: 4;
  display: block;
  height: auto;
  object-fit: contain;
  filter: drop-shadow(0 18px 16px rgba(68, 34, 85, 0.16));
  pointer-events: none;
  opacity: 0;
  transition: opacity 180ms ease;
}

.agent-sprite-work {
  width: 34%;
  left: 8%;
  bottom: 14%;
  transform-origin: 48% 78%;
}

.agent-sprite-chat {
  width: 14.2%;
  left: 43.2%;
  bottom: 25.5%;
  transform-origin: 50% 78%;
}

.agent-life-bubble {
  position: absolute;
  z-index: 5;
  left: 28%;
  top: 20%;
  max-width: 190px;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  padding: 9px 13px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.88);
  color: var(--purple);
  font-size: 13px;
  font-weight: 900;
  line-height: 1.15;
  box-shadow: 0 16px 36px rgba(76, 0, 87, 0.12);
  backdrop-filter: blur(12px);
}

.agent-life-bubble::before {
  content: "";
  width: 8px;
  height: 8px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--pink);
  box-shadow: 0 0 0 5px rgba(255, 79, 120, 0.12);
}

.agent-life-card[data-agent-phase="chatting"] .agent-sprite-chat,
.agent-life-card[data-agent-mode="image"][data-agent-phase="idle"] .agent-sprite-work,
.agent-life-card[data-agent-mode="video"][data-agent-phase="idle"] .agent-sprite-work,
.agent-life-card[data-agent-mode="copy"][data-agent-phase="idle"] .agent-sprite-work,
.agent-life-card[data-agent-mode="schedule"][data-agent-phase="idle"] .agent-sprite-work,
.agent-life-card[data-agent-mode="command"][data-agent-phase="idle"] .agent-sprite-work,
.agent-life-card[data-agent-phase="working"] .agent-sprite-work,
.agent-life-card[data-agent-phase="done"][data-agent-mode="chat"] .agent-sprite-chat,
.agent-life-card[data-agent-phase="done"]:not([data-agent-mode="chat"]) .agent-sprite-work {
  opacity: 1;
}

.agent-life-card[data-agent-phase="walking"] .agent-sprite-chat {
  opacity: 1;
  animation: agentWalkToDesk 1.45s ease-in-out forwards;
}

.agent-life-card[data-agent-phase="returning"] .agent-sprite-chat {
  opacity: 1;
  animation: agentWalkBack 1.25s ease-in-out forwards;
}

.agent-life-card[data-agent-phase="returning"][data-agent-mode="chat"] .agent-sprite-chat {
  animation: agentChatBackToBed 1.15s ease-in-out forwards;
}

.agent-life-card[data-agent-phase="walking"] .agent-life-route,
.agent-life-card[data-agent-phase="returning"] .agent-life-route {
  opacity: 1;
}

.agent-life-card[data-agent-phase="working"] .agent-sprite-work {
  animation: agentTypeLoop 0.58s ease-in-out infinite;
}

.agent-life-card[data-agent-phase="chatting"] .agent-sprite-chat {
  animation: agentChatLoop 1.8s ease-in-out infinite;
}

.agent-life-card[data-agent-phase="done"] .agent-sprite-work {
  animation: agentDoneBounce 0.9s ease-in-out 1;
}

.agent-life-card[data-agent-phase="done"][data-agent-mode="chat"] .agent-sprite-chat {
  animation: agentDoneBounce 0.9s ease-in-out 1;
}

.agent-life-card[data-agent-phase="idle"][data-idle-activity="sleep"] .agent-life-bubble,
.agent-life-card[data-agent-phase="wake"] .agent-life-bubble {
  left: 71%;
  top: 17%;
}

.agent-life-card[data-agent-phase="chatting"] .agent-life-bubble,
.agent-life-card[data-agent-phase="returning"] .agent-life-bubble {
  left: 50.2%;
  top: 17%;
}

.agent-life-card[data-agent-phase="walking"] .agent-life-bubble {
  left: 47%;
  top: 18%;
}

@keyframes agentSleepBreath {
  0%, 100% { transform: translateY(0) rotate(-1deg) scale(1); }
  50% { transform: translateY(-3px) rotate(0.5deg) scale(1.012); }
}

@keyframes agentChatLoop {
  0%, 100% { transform: translateY(0) rotate(-1deg); }
  50% { transform: translateY(-5px) rotate(1deg); }
}

@keyframes agentTypeLoop {
  0%, 100% { transform: translateY(0) rotate(-0.5deg); }
  50% { transform: translateY(-3px) rotate(0.5deg); }
}

@keyframes agentDoneBounce {
  0%, 100% { transform: translateY(0) scale(1); }
  35% { transform: translateY(-12px) scale(1.04); }
  65% { transform: translateY(0) scale(0.98); }
}

@keyframes agentWalkToDesk {
  0% { left: 66.5%; bottom: 25.5%; transform: scale(0.62); }
  45% { left: 45%; bottom: 25.5%; transform: scale(0.68); }
  100% { left: 27%; bottom: 25.2%; transform: scale(0.58); }
}

@keyframes agentWalkBack {
  0% { left: 27%; bottom: 25.2%; transform: scale(0.58); }
  50% { left: 45%; bottom: 25.5%; transform: scale(0.68); }
  100% { left: 66.5%; bottom: 25.5%; transform: scale(0.62); }
}

@keyframes agentChatBackToBed {
  0% { left: 43.2%; bottom: 25.5%; transform: scale(1); }
  55% { left: 55%; bottom: 25.8%; transform: scale(0.78); }
  100% { left: 66.5%; bottom: 25.5%; transform: scale(0.62); }
}

