.iso-rug,
.iso-bed,
.iso-pillow,
.iso-track,
.iso-track-rail,
.iso-desk,
.iso-desk-leg,
.iso-monitor,
.iso-keyboard,
.iso-phone,
.iso-station,
.iso-card-float,
.iso-shadow {
  position: absolute;
  display: block;
  box-sizing: border-box;
}

.iso-floor {
  left: 4%;
  right: 4%;
  bottom: 8%;
  height: 58%;
  border: 2px solid rgba(93, 8, 108, 0.08);
  background: linear-gradient(135deg, #ffffff 0%, #fff2f8 100%);
  clip-path: polygon(50% 0, 100% 28%, 50% 100%, 0 28%);
  box-shadow: 0 18px 0 rgba(93, 8, 108, 0.08);
}

.iso-wall {
  background: linear-gradient(180deg, rgba(243, 218, 249, 0.9), rgba(255, 248, 252, 0.92));
  border: 1px solid rgba(93, 8, 108, 0.07);
}

.iso-wall-back {
  left: 32%;
  top: 2%;
  width: 40%;
  height: 43%;
  transform: skewY(29deg);
  transform-origin: bottom left;
}

.iso-wall-side {
  right: 7%;
  top: 8%;
  width: 33%;
  height: 42%;
  transform: skewY(-29deg);
  transform-origin: bottom right;
  background: linear-gradient(180deg, rgba(255, 231, 250, 0.9), rgba(255, 250, 254, 0.94));
}

.iso-rug {
  left: 20%;
  bottom: 22%;
  width: 34%;
  height: 17%;
  background: rgba(255, 79, 120, 0.08);
  clip-path: polygon(50% 0, 100% 28%, 50% 100%, 0 28%);
}

.iso-bed {
  left: 15%;
  bottom: 34%;
  width: 25%;
  height: 13%;
  border-radius: 8px;
  background: linear-gradient(135deg, #fff, #ffdfea);
  transform: skewY(-20deg);
  box-shadow: 10px 12px 0 rgba(93, 8, 108, 0.12);
}

.iso-pillow {
  left: 32%;
  bottom: 42%;
  width: 10%;
  height: 7%;
  border-radius: 7px;
  background: #fff;
  transform: skewY(-20deg);
}

.iso-track {
  right: 18%;
  bottom: 26%;
  width: 25%;
  height: 10%;
  border-radius: 8px;
  background: #2a1730;
  transform: skewY(18deg);
  box-shadow: 8px 10px 0 rgba(93, 8, 108, 0.12);
}

.iso-track-rail {
  right: 24%;
  bottom: 38%;
  width: 18%;
  height: 20%;
  border: 5px solid var(--purple);
  border-bottom: 0;
  border-radius: 8px 8px 0 0;
  transform: skewY(14deg);
}

.iso-desk {
  right: 18%;
  bottom: 32%;
  width: 37%;
  height: 16%;
  border-radius: 8px;
  background: linear-gradient(135deg, #fff, #f8eef9);
  transform: skewY(-18deg);
  box-shadow: 12px 14px 0 rgba(93, 8, 108, 0.13);
}

.iso-desk-leg {
  width: 4%;
  height: 18%;
  border-radius: 4px;
  background: #8e739a;
}

.iso-desk-leg-a {
  right: 50%;
  bottom: 19%;
}

.iso-desk-leg-b {
  right: 20%;
  bottom: 23%;
}

.iso-monitor {
  right: 31%;
  bottom: 48%;
  width: 19%;
  height: 25%;
  border-radius: 8px;
  background: #17071d;
  transform: skewY(9deg);
  box-shadow: 6px 7px 0 rgba(93, 8, 108, 0.14);
}

.iso-monitor::after {
  content: "";
  position: absolute;
  left: 16%;
  top: 18%;
  width: 68%;
  height: 12%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--pink), var(--gold));
  opacity: 0.85;
}

.iso-keyboard {
  right: 32%;
  bottom: 40%;
  width: 18%;
  height: 4%;
  border-radius: 5px;
  background: #eadcea;
  transform: skewY(-18deg);
}

.iso-phone {
  right: 23%;
  bottom: 41%;
  width: 8%;
  height: 12%;
  border-radius: 5px;
  background: #1f1028;
  transform: rotate(-12deg) skewY(-14deg);
}

.iso-station {
  opacity: 0;
  transition: opacity 180ms ease, transform 180ms ease;
}

.iso-station-image {
  left: 21%;
  top: 20%;
  width: 20%;
  height: 22%;
  border-radius: 8px;
  background: linear-gradient(135deg, #fff, #ffe5f0);
  border: 4px solid rgba(255, 79, 120, 0.4);
  transform: skewY(24deg);
}

.iso-station-video {
  left: 19%;
  top: 27%;
  width: 22%;
  height: 10%;
  border-radius: 7px;
  background: linear-gradient(90deg, var(--pink) 0 30%, var(--gold) 30% 58%, var(--blue, #62a8ff) 58%);
  box-shadow: 0 9px 0 rgba(93, 8, 108, 0.1);
}

.iso-station-copy {
  left: 18%;
  top: 24%;
  width: 22%;
  height: 17%;
  border-radius: 8px;
  background: #fff;
  border: 1px solid rgba(93, 8, 108, 0.12);
  box-shadow: inset 0 10px 0 rgba(244, 202, 50, 0.28);
}

.iso-station-schedule {
  left: 18%;
  top: 22%;
  width: 24%;
  height: 21%;
  border-radius: 8px;
  background:
    linear-gradient(90deg, transparent 31%, rgba(93, 8, 108, 0.1) 32% 33%, transparent 34% 64%, rgba(93, 8, 108, 0.1) 65% 66%, transparent 67%),
    linear-gradient(180deg, var(--blue, #62a8ff) 0 24%, #fff 24%);
}

.iso-station-command {
  left: 19%;
  top: 25%;
  width: 23%;
  height: 15%;
  border-radius: 8px;
  background: #27132d;
  box-shadow:
    inset 18px 0 0 rgba(255, 79, 120, 0.72),
    inset -18px 0 0 rgba(79, 209, 180, 0.6);
}

.iso-card-float {
  z-index: 5;
  min-width: 70px;
  max-width: 112px;
  padding: 7px 9px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.88);
  color: var(--purple);
  font-size: 11px;
  font-weight: 900;
  line-height: 1.15;
  box-shadow: 0 8px 18px rgba(76, 0, 87, 0.1);
}

.iso-card-one {
  left: 8%;
  top: 22%;
  animation: isoFloat 3.2s ease-in-out infinite;
}

.iso-card-two {
  right: 8%;
  top: 26%;
  animation: isoFloat 3.6s ease-in-out 0.35s infinite;
}

.iso-card-three {
  right: 14%;
  bottom: 30%;
  animation: isoFloat 3.4s ease-in-out 0.7s infinite;
}

.agent-iso-mascot {
  position: absolute;
  z-index: 6;
  left: 46%;
  bottom: 41%;
  width: 25%;
  max-width: 124px;
  height: auto;
  transform: translateX(-50%);
  filter: drop-shadow(0 15px 10px rgba(76, 0, 87, 0.16));
  animation: isoMascotWork 2.2s ease-in-out infinite;
}

.iso-shadow {
  z-index: 4;
  left: 37%;
  bottom: 34%;
  width: 23%;
  height: 9%;
  border-radius: 999px;
  background: rgba(76, 0, 87, 0.13);
  transform: skewX(-28deg);
  filter: blur(2px);
}

.agent-iso-card[data-agent-mode="idle"] .iso-desk,
.agent-iso-card[data-agent-mode="idle"] .iso-desk-leg,
.agent-iso-card[data-agent-mode="idle"] .iso-monitor,
.agent-iso-card[data-agent-mode="idle"] .iso-keyboard,
.agent-iso-card[data-agent-mode="idle"] .iso-phone {
  opacity: 0.34;
}

.agent-iso-card[data-agent-mode="idle"] .agent-iso-mascot {
  left: 31%;
  bottom: 46%;
  width: 24%;
  animation-name: isoMascotIdle;
}

.agent-iso-card:not([data-agent-mode="idle"]) .iso-bed,
.agent-iso-card:not([data-agent-mode="idle"]) .iso-pillow,
.agent-iso-card:not([data-agent-mode="idle"]) .iso-track,
.agent-iso-card:not([data-agent-mode="idle"]) .iso-track-rail {
  opacity: 0.18;
}

.agent-iso-card[data-agent-mode="image"] .iso-station-image,
.agent-iso-card[data-agent-mode="video"] .iso-station-video,
.agent-iso-card[data-agent-mode="copy"] .iso-station-copy,
.agent-iso-card[data-agent-mode="schedule"] .iso-station-schedule,
.agent-iso-card[data-agent-mode="command"] .iso-station-command {
  opacity: 1;
  transform: translateY(-3px);
}

@keyframes isoFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

@keyframes isoMascotWork {
  0%, 100% { transform: translateX(-50%) translateY(0) rotate(-1deg); }
  50% { transform: translateX(-50%) translateY(-5px) rotate(1deg); }
}

@keyframes isoMascotIdle {
  0%, 100% { transform: translateX(-50%) translateY(0) rotate(-8deg); }
  50% { transform: translateX(-50%) translateY(-4px) rotate(-4deg); }
}

.agent-3d-copy {
  position: relative;
  z-index: 2;
  display: grid;
  gap: 9px;
  padding: 0 18px 18px;
}

.agent-3d-copy h2 {
  margin: 0;
  color: var(--purple);
  font-size: 21px;
  line-height: 1.15;
  letter-spacing: 0;
}

.agent-3d-copy p {
  margin: 0;
  color: rgba(93, 8, 108, 0.68);
  font-size: 13px;
  line-height: 1.5;
}

.agent-3d-task-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 2px;
}

.agent-3d-task-row span {
  max-width: 100%;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.82);
  overflow-wrap: anywhere;
}

.agent-quick-actions {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.agent-quick-actions button {
  min-height: 58px;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 8px;
  padding: 12px 14px;
  background: rgba(255, 255, 255, 0.9);
  color: var(--purple);
  font-weight: 850;
  text-align: left;
  line-height: 1.25;
  box-shadow: 0 12px 28px rgba(76, 0, 87, 0.08);
}

.agent-quick-actions button:hover {
  border-color: rgba(255, 79, 101, 0.26);
  background: #fff4f8;
}

.agent-page-panel {
  width: 100%;
  height: calc(100vh - 128px);
  max-height: calc(100vh - 128px);
  min-height: 620px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.95);
  box-shadow: var(--shadow);
}

.agent-page-panel header {
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(93, 8, 108, 0.1);
}

.agent-page-panel h3 {
  margin: 0;
  color: var(--purple);
  font-size: 24px;
}

.agent-header-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.agent-header-actions .mini-button {
  min-height: 36px;
  border-radius: 11px;
  padding: 8px 11px;
  font-size: 13px;
  font-weight: 950;
}

.agent-page-panel .agent-thread {
  min-height: 0;
  padding: 16px 4px 16px 0;
}

.agent-history-panel {
  display: grid;
  gap: 12px;
  margin: 16px 0 10px;
  border: 1px solid rgba(93, 8, 108, 0.12);
  border-radius: 18px;
  padding: 14px;
  background: linear-gradient(135deg, rgba(255, 248, 251, 0.98), rgba(248, 237, 255, 0.92));
  box-shadow: 0 18px 44px rgba(93, 8, 108, 0.08);
}

.agent-history-panel header,
.agent-history-list article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.agent-history-panel header strong {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--purple);
  font-size: 15px;
  font-weight: 950;
}

.agent-history-panel header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
}

.agent-history-panel header > small {
  color: rgba(93, 8, 108, 0.54);
  font-size: 12px;
  font-weight: 850;
}

.agent-history-close,
.agent-history-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.86);
  color: rgba(47, 6, 58, 0.82);
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease, color 0.16s ease;
}

.agent-history-close:hover,
.agent-history-action:hover {
  transform: translateY(-1px);
  border-color: rgba(93, 8, 108, 0.22);
  background: #fff;
  color: var(--purple);
}

.agent-history-list {
  display: grid;
  gap: 10px;
}

.agent-history-list article {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  border: 1px solid rgba(93, 8, 108, 0.09);
  border-radius: 14px;
  padding: 12px 12px 12px 14px;
  background: rgba(255, 255, 255, 0.82);
}

.agent-history-item-main {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.agent-history-actions {
  display: inline-flex;
  gap: 8px;
}

.agent-history-action.primary {
  background: rgba(93, 8, 108, 0.08);
  color: var(--purple);
}

.agent-history-action.danger {
  color: rgba(55, 45, 62, 0.72);
}

.agent-history-action.danger:hover {
  border-color: rgba(255, 85, 116, 0.28);
  color: #ff5574;
}

.agent-history-list b,
.agent-history-empty {
  color: rgba(31, 6, 38, 0.92);
  font-weight: 900;
}

.agent-history-list small,
.agent-history-empty {
  color: rgba(93, 8, 108, 0.62);
  font-size: 13px;
}

.agent-history-list b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-history-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.agent-history-footer-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 38px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 12px;
  padding: 8px 12px;
  background: rgba(93, 8, 108, 0.07);
  color: var(--purple);
  font-size: 13px;
  font-weight: 950;
  cursor: pointer;
}

.agent-history-footer-action.danger {
  background: rgba(255, 255, 255, 0.7);
  color: rgba(47, 6, 58, 0.72);
}

.agent-page-panel .agent-thread article {
  max-width: min(680px, 90%);
  border-color: rgba(93, 8, 108, 0.12);
  background: #fff;
  box-shadow: 0 14px 34px rgba(93, 8, 108, 0.08);
}

.agent-page-panel .agent-thread article.assistant {
  border-color: rgba(93, 8, 108, 0.1);
  background: linear-gradient(180deg, #fff, #fff8fb);
}

.agent-history-compact {
  max-width: min(720px, 92%);
  display: grid;
  grid-template-columns: 20px minmax(0, auto) minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 14px;
  padding: 10px 12px;
  background: rgba(93, 8, 108, 0.045);
  color: rgba(31, 6, 38, 0.82);
}

.agent-history-compact span {
  color: var(--purple) !important;
  font-size: 13px;
  font-weight: 950;
}

.agent-history-compact small {
  overflow: hidden;
  color: rgba(93, 8, 108, 0.62);
  font-size: 12px;
  font-weight: 760;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-history-compact button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 30px;
  border: 0;
  border-radius: 999px;
  padding: 6px 10px;
  background: rgba(93, 8, 108, 0.08);
  color: var(--purple);
  font-size: 12px;
  font-weight: 950;
}

.agent-page-panel .agent-thread article.assistant > p {
  color: rgba(31, 6, 38, 0.92);
  font-weight: 760;
}

.agent-page-panel .agent-message {
  display: grid;
  gap: 10px;
  color: rgba(31, 6, 38, 0.95);
  font-size: 15px;
  font-weight: 760;
  line-height: 1.52;
}

.agent-page-panel .agent-message p,
.agent-page-panel .agent-message ul,
.agent-page-panel .agent-message ol {
  margin: 0;
}

.agent-page-panel .agent-message ul,
.agent-page-panel .agent-message ol {
  display: grid;
  gap: 6px;
  padding-left: 22px;
}

.agent-page-panel .agent-message strong {
  color: #4f055f;
  font-weight: 950;
}

.agent-page-panel .agent-message code {
  border-radius: 6px;
  padding: 1px 6px;
  background: rgba(93, 8, 108, 0.08);
  color: var(--purple);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.92em;
}

.agent-message-table {
  overflow-x: auto;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.72);
}

.agent-message-table table {
  width: 100%;
  border-collapse: collapse;
}

.agent-message-table th,
.agent-message-table td {
  color: rgba(31, 6, 38, 0.88);
  border-bottom: 1px solid rgba(93, 8, 108, 0.08);
  padding: 10px 12px;
  vertical-align: top;
  font-weight: 820;
}

.agent-message-table th {
  background: rgba(93, 8, 108, 0.06);
  color: rgba(31, 6, 38, 0.86);
  font-size: 13px;
  font-weight: 950;
  text-align: left;
}

.agent-message-table tr:last-child td {
  border-bottom: 0;
}

.agent-page-panel .agent-thread article.user {
  background: #fff8ec;
  border-color: rgba(244, 202, 50, 0.44);
}

.agent-page-panel .agent-thread article.user p {
  color: var(--purple);
}

.agent-page-panel .agent-thread article.agent-thinking {
  max-width: min(560px, 94%);
  gap: 10px;
  padding: 14px 16px;
  border-color: rgba(244, 202, 50, 0.3);
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(244, 202, 50, 0.12), rgba(255, 255, 255, 0.72) 58%),
    #fffaf2;
  box-shadow: 0 12px 30px rgba(93, 8, 108, 0.07);
}

.agent-thinking > span {
  color: rgba(93, 8, 108, 0.7) !important;
  font-size: 13px !important;
  font-weight: 900 !important;
}

.agent-thinking-row {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
}

.agent-thinking-row b {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: rgba(244, 202, 50, 0.18);
  color: var(--purple);
}

.agent-thinking-row b svg {
  animation: spin 1s linear infinite;
}

.agent-thinking-row strong {
  display: block;
  color: var(--purple);
  font-size: 16px;
  font-weight: 950;
  line-height: 1.25;
}

.agent-thinking-row p {
  margin-top: 4px !important;
  color: rgba(93, 8, 108, 0.68) !important;
  font-size: 14px !important;
  font-weight: 720 !important;
  line-height: 1.35 !important;
}

.agent-thinking-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 2px;
}

.agent-thinking-steps span {
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 999px;
  padding: 5px 9px;
  background: rgba(255, 255, 255, 0.7);
  color: rgba(93, 8, 108, 0.36);
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
}

.agent-thinking-steps span.done {
  border-color: rgba(34, 199, 120, 0.22);
  background: rgba(34, 199, 120, 0.09);
  color: rgba(14, 120, 76, 0.9);
}

.agent-thinking-steps span.active {
  border-color: rgba(93, 8, 108, 0.22);
  background: rgba(93, 8, 108, 0.08);
  color: var(--purple);
  animation: agentStepPulse 1.4s ease-in-out infinite;
}

.agent-thinking-track {
  height: 3px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(93, 8, 108, 0.08);
}

.agent-thinking-track i {
  display: block;
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--gold), var(--pink));
  animation: agentThinkingSlide 1.25s ease-in-out infinite;
}

@keyframes agentThinkingSlide {
  0% { transform: translateX(-110%); }
  100% { transform: translateX(250%); }
}

@keyframes agentStepPulse {
  0%, 100% { box-shadow: 0 0 0 rgba(93, 8, 108, 0); }
  50% { box-shadow: 0 0 0 4px rgba(93, 8, 108, 0.08); }
}

@media (prefers-reduced-motion: reduce) {
  .agent-thinking-row b svg,
  .agent-thinking-track i,
  .agent-thinking-steps span.active {
    animation: none !important;
  }
}

.agent-run-card {
  display: grid;
  gap: 10px;
  margin-top: 14px;
  border: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 10px;
  padding: 12px;
  background: #fffaf2;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

.agent-run-card[data-agent-run-status="completed"] {
  display: inline-grid;
  width: fit-content;
  max-width: 100%;
  gap: 4px;
  padding: 10px 12px;
  background: rgba(35, 197, 123, 0.08);
  border-color: rgba(35, 197, 123, 0.2);
}

.agent-run-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.agent-run-head strong {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: rgba(31, 6, 38, 0.9);
