.agent-page-panel .agent-thread .agent-run-card span {
  color: inherit;
}

.agent-page-panel .agent-thread .agent-run-head span {
  color: rgba(93, 8, 108, 0.72);
}

.agent-page-panel .agent-thread .agent-confidence span {
  color: rgba(255, 255, 255, 0.52);
}

.agent-page-panel .agent-form {
  grid-template-columns: minmax(0, 1fr) 52px;
  gap: 10px;
  align-items: end;
  padding: 10px;
  border-top: 1px solid rgba(93, 8, 108, 0.1);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 14px 34px rgba(93, 8, 108, 0.08);
}

.agent-page-panel .agent-form textarea {
  min-height: 48px;
  max-height: 132px;
  overflow-y: auto;
  border-color: rgba(93, 8, 108, 0.12);
  border-radius: 14px;
  padding: 13px 15px;
  background: #fff;
  color: rgba(31, 6, 38, 0.94);
  font-size: 15.5px;
  font-weight: 760;
  line-height: 1.35;
  resize: none;
}

.agent-page-panel .agent-form textarea:focus {
  border-color: rgba(152, 28, 169, 0.42);
  box-shadow: 0 0 0 4px rgba(244, 202, 50, 0.14);
}

.agent-page-panel .agent-form textarea:disabled {
  background: rgba(93, 8, 108, 0.04);
  color: rgba(31, 6, 38, 0.46);
}

.agent-send-button {
  width: 52px;
  min-width: 52px;
  min-height: 48px;
  border-radius: 14px;
  padding: 0;
}

.agent-send-button span {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.support-bubble {
  background: linear-gradient(135deg, var(--pink), var(--coral));
  border-color: rgba(255, 79, 101, 0.24);
  box-shadow: 0 18px 42px rgba(255, 79, 101, 0.28);
}

.support-form {
  display: grid;
  gap: 14px;
}

.support-form textarea {
  min-height: 150px;
}

@media (max-width: 1000px) {
  .agent-workbench {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .agent-visual-column {
    position: static;
  }

  .agent-page-hero {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .agent-3d-card {
    min-height: 400px;
  }

  .agent-page-panel {
    height: auto;
    max-height: none;
    min-height: min(720px, calc(100vh - 120px));
  }
}

@media (max-width: 640px) {
  .agent-page-hero {
    padding: 18px;
  }

  .agent-page-hero h1 {
    font-size: clamp(30px, 10vw, 42px);
  }

  .agent-3d-card {
    min-height: 370px;
    grid-template-rows: auto minmax(230px, 1fr) auto;
  }

  .agent-life-card {
    min-height: 430px;
  }

  .agent-life-stage {
    min-height: 250px;
  }

  .agent-life-render-image {
    width: 128%;
    left: 50%;
    transform: translateX(-50%);
  }

  .agent-3d-status {
    top: 10px;
    left: 10px;
    right: 10px;
  }

  .agent-3d-status span,
  .agent-3d-status b {
    padding: 8px 9px;
    font-size: 11px;
  }

  .agent-3d-stage {
    min-height: 238px;
  }

  .agent-3d-copy {
    padding: 0 14px 14px;
  }

  .agent-3d-copy h2 {
    font-size: 18px;
  }

  .agent-page-panel {
    min-height: calc(100vh - 96px);
  }
}

/* Sidebar menu alignment */
.sidebar .side-primary,
.sidebar .side-link,
.sidebar .new-project,
.sidebar .project-button {
  display: flex;
  width: 100%;
  flex-shrink: 0;
  justify-content: flex-start;
  text-align: left;
  gap: 12px;
  padding-left: 18px;
  padding-right: 14px;
}

.sidebar .side-primary svg,
.sidebar .side-link svg,
.sidebar .new-project svg,
.sidebar .project-button svg {
  flex: 0 0 24px;
}

.sidebar .side-link svg:first-child {
  margin-left: 0;
}

.sidebar .side-link svg + svg:last-child {
  flex-basis: 14px;
  margin-left: auto;
}

.sidebar .side-section {
  justify-content: flex-start;
  text-align: left;
}

@media (max-width: 700px) {
  .public-nav {
    padding-right: 0;
    padding-top: 58px;
  }

  .global-lang-dock {
    top: 10px;
    right: 10px;
  }

  .global-lang-dock .lang-switch {
    grid-template-columns: 15px auto 14px;
    min-width: 88px;
    min-height: 40px;
    padding: 8px 10px;
  }

  .global-lang-dock .lang-switch small {
    display: none;
  }

  .global-lang-dock .lang-options {
    min-width: 88px;
  }
}

/* Project list action menu */
.studio-shell .project-list {
  display: grid;
  gap: 6px;
}

.project-menu-item {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 30px;
  align-items: center;
  min-height: 52px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease;
}

.project-menu-item.active {
  border-color: rgba(255, 78, 120, 0.58);
  background: linear-gradient(135deg, rgba(255, 78, 120, 0.2), rgba(255, 131, 94, 0.08));
  box-shadow:
    inset 3px 0 0 #ff4e78,
    0 10px 24px rgba(255, 78, 120, 0.12);
}

.project-menu-item.menu-open {
  z-index: 30;
}

.studio-shell .project-menu-item .project-button {
  min-height: 50px;
  margin: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  color: rgba(255, 255, 255, 0.7);
  font-size: 15px;
  line-height: 1.2;
  gap: 10px;
  padding-left: 12px;
  padding-right: 8px;
}

.studio-shell .project-menu-item .project-button.active {
  background: transparent;
  box-shadow: none;
  color: #fff;
}

.studio-shell .project-menu-item .project-button span:last-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-icon {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.72);
  flex: 0 0 32px;
}

.project-menu-item.active .project-icon {
  border-color: transparent;
  background: linear-gradient(135deg, #ff4e78, #ff835e);
  color: #fff;
  box-shadow: 0 10px 20px rgba(255, 78, 120, 0.2);
}

.studio-shell .project-icon svg,
.studio-shell .project-button.active .project-icon svg {
  width: 18px !important;
  height: 18px !important;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: currentColor;
}

.project-more {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: rgba(255, 255, 255, 0.48);
  opacity: 0;
  transition:
    opacity 0.18s ease,
    background 0.18s ease,
    color 0.18s ease;
}

.project-menu-item:hover .project-more,
.project-menu-item.active .project-more,
.project-menu-item:focus-within .project-more {
  opacity: 1;
}

.project-more:hover {
  background: rgba(255, 255, 255, 0.09);
  color: #fff;
}

.project-action-menu {
  position: absolute;
  top: calc(100% - 20px);
  right: 14px;
  z-index: 90;
  width: 210px;
  display: grid;
  gap: 6px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 14px;
  padding: 10px;
  background: rgba(18, 18, 19, 0.98);
  box-shadow: 0 22px 54px rgba(0, 0, 0, 0.38);
  transform-origin: right top;
  animation: projectMenuIn 0.16s ease both;
}

.project-action-menu button {
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 0;
  border-radius: 10px;
  padding: 10px 12px;
  background: transparent;
  color: #fff;
  font-weight: 900;
  text-align: left;
}

.project-action-menu button:hover {
  background: rgba(255, 255, 255, 0.08);
}

.project-action-menu .danger {
  color: #ff5f6f;
}

@keyframes projectMenuIn {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.delete-confirm {
  display: grid;
  gap: 20px;
}

.delete-confirm p {
  color: var(--muted);
  line-height: 1.55;
}

.delete-confirm p b {
  color: var(--purple);
}

.delete-confirm div {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

.danger-button {
  background: linear-gradient(135deg, #ff435e, #ff835e);
}

.sidebar-account-panel {
  display: grid;
  gap: 9px;
  margin: auto -2px 0;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-credit-card,
.sidebar-subscription-card {
  border: 1px solid rgba(255, 211, 26, 0.14);
  border-radius: 14px;
  padding: 11px;
  background:
    radial-gradient(circle at 84% 0, rgba(255, 211, 26, 0.09), transparent 34%),
    linear-gradient(135deg, rgba(50, 20, 12, 0.58), rgba(18, 17, 17, 0.92));
}

.sidebar-credit-card {
  display: grid;
  gap: 8px;
  box-shadow: 0 12px 28px rgba(255, 117, 53, 0.08);
}

.sidebar-credit-card > span {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #ffd31a;
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.sidebar-credit-card b {
  color: #fff;
  font-size: 28px;
  line-height: 1;
}

.sidebar-credit-card button {
  min-height: 36px;
  justify-content: center;
  border: 0;
  border-radius: 12px;
  background: #ffd31a;
  color: #090909;
  font-size: 15px;
  font-weight: 950;
  box-shadow: 0 12px 24px rgba(255, 211, 26, 0.16);
}

.sidebar-subscription-card {
  display: grid;
  gap: 5px;
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.055);
}

.sidebar-subscription-card strong {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #20e178;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.sidebar-subscription-card strong i {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #20e178;
  box-shadow: 0 0 0 5px rgba(32, 225, 120, 0.12);
}

.sidebar-subscription-card strong em {
  color: rgba(255, 255, 255, 0.38);
  font-style: normal;
}

.sidebar-subscription-card span {
  color: rgba(255, 255, 255, 0.46);
  font-size: 12px;
}

.sidebar-subscription-card.expired strong,
.sidebar-subscription-card.expired span {
  color: #ff6678;
}

.sidebar-subscription-card.expired strong i {
  background: #ff6678;
  box-shadow: 0 0 0 6px rgba(255, 102, 120, 0.12);
}

.sidebar-user-card {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
}

.sidebar-avatar {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #ffd31a;
  color: #fff;
  font-size: 18px;
  font-weight: 950;
  box-shadow: 0 12px 22px rgba(255, 117, 53, 0.18);
}

.sidebar-user-card b,
.sidebar-user-card small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebar-user-card b {
  color: #fff;
  font-size: 15px;
}

.sidebar-user-card small {
  margin-top: 3px;
  color: rgba(255, 255, 255, 0.42);
  font-size: 11px;
}

.sidebar-account-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.sidebar-account-actions button {
  min-height: 36px;
  justify-content: center;
  border: 1px solid rgba(255, 211, 26, 0.26);
  border-radius: 11px;
  background: rgba(255, 117, 53, 0.08);
  color: #ffd31a;
  font-size: 13px;
  font-weight: 950;
}

.sidebar-account-actions button:last-child {
  border-color: rgba(255, 95, 111, 0.32);
  background: rgba(255, 95, 111, 0.1);
  color: #ffb0b8;
}

.sidebar-account-actions button.active {
  background: rgba(255, 211, 26, 0.16);
}

.canvas-card.slim:has(.settings-page) {
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.settings-page {
  display: grid;
  gap: 20px;
}

.settings-card {
  display: grid;
  gap: 22px;
  border: 1px solid rgba(75, 0, 94, 0.11);
  border-radius: 24px;
  padding: clamp(24px, 3.2vw, 40px);
  background:
    radial-gradient(circle at 96% 6%, rgba(255, 63, 110, 0.12), transparent 30%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(255, 247, 251, 0.98) 52%, rgba(246, 236, 255, 0.94));
  color: var(--studio-purple-900, #2a0633);
  box-shadow: 0 20px 54px rgba(75, 0, 94, 0.09);
}

.settings-card header {
  display: flex;
  align-items: center;
  gap: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(75, 0, 94, 0.1);
}

.settings-card header > span {
  width: 64px;
  height: 64px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 63, 110, 0.18);
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(255, 63, 110, 0.12), rgba(255, 255, 255, 0.9));
  color: var(--studio-pink, #f35b6c);
  box-shadow: 0 14px 30px rgba(255, 63, 110, 0.12);
}

.whatsapp-settings-card header > span {
  border-color: rgba(255, 63, 110, 0.18);
  background: linear-gradient(135deg, rgba(255, 63, 110, 0.12), rgba(255, 255, 255, 0.9));
  color: var(--studio-pink, #f35b6c);
}

.password-settings-card header > span {
  border-color: rgba(75, 0, 94, 0.16);
  background: linear-gradient(135deg, rgba(75, 0, 94, 0.1), rgba(255, 247, 251, 0.94));
  color: var(--studio-purple-700, #5d086c);
}

.settings-card h2 {
  margin: 0;
  color: var(--studio-purple-900, #2a0633);
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1;
}

.settings-card p {
  margin: 8px 0 0;
  color: rgba(43, 6, 56, 0.62);
  font-size: 16px;
  font-weight: 800;
}

.settings-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.settings-card label {
  display: grid;
  gap: 10px;
  color: rgba(75, 0, 94, 0.72);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 13px;
  font-weight: 950;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.settings-card input {
  min-height: 62px;
  border: 1px solid rgba(75, 0, 94, 0.14);
  border-radius: 16px;
  padding: 0 22px;
  background: rgba(255, 255, 255, 0.94);
  color: var(--studio-purple-900, #2a0633);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 10px 24px rgba(75, 0, 94, 0.045);
}

.settings-card input:disabled {
  background: rgba(246, 236, 255, 0.58);
  color: rgba(43, 6, 56, 0.82);
  opacity: 1;
}

.settings-card .gold-button {
  width: fit-content;
  min-width: 220px;
  min-height: 56px;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--studio-pink, #f35b6c), var(--studio-coral, #ff7a5c));
  color: #fff;
  font-size: 17px;
  box-shadow: 0 18px 38px rgba(255, 63, 110, 0.2);
}

@media (max-width: 900px) {
  .settings-form-grid,
  .sidebar-account-actions {
    grid-template-columns: 1fr;
  }

  .settings-card input {
    min-height: 62px;
    font-size: 18px;
  }
}

.canvas-card.slim:has(.topup-experience) {
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.canvas-card.slim:has(.usage-experience) {
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.usage-experience {
  display: grid;
  gap: 26px;
}

.usage-summary-grid {
