}

.usage-summary-card small {
  color: rgba(255, 255, 255, 0.48);
  font-size: 18px;
}

.usage-summary-card.spend b {
  color: #8e3cff;
}

.usage-summary-card.image b {
  color: #356dff;
}

.usage-summary-card.video b {
  color: var(--pink);
}

.usage-summary-card.auto b {
  color: #f39a15;
}

.usage-ledger-panel {
  display: grid;
  gap: 20px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 24px;
  padding: clamp(24px, 4vw, 42px);
  background: #151515;
  color: #fff;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.18);
}

.usage-filter-row {
