  margin: 0 auto;
  padding: clamp(30px, 4vw, 62px);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 32px;
  background: #130715;
  box-shadow:
    0 38px 110px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  isolation: isolate;
}

.video-scene-bg {
  position: absolute;
  inset: -3% -8% -3% 28%;
  z-index: 0;
  width: 82%;
  height: 108%;
  object-fit: cover;
  object-position: 62% center;
  filter: saturate(1.08) contrast(1.03);
  transform: scale(1.01);
  animation: videoSceneBreath 7.5s ease-in-out infinite alternate;
}

.video-scene-vignette {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(13, 3, 16, 0.98) 0%, rgba(15, 4, 18, 0.96) 36%, rgba(18, 5, 22, 0.42) 55%, rgba(18, 5, 22, 0.1) 78%, rgba(18, 5, 22, 0.24) 100%),
    linear-gradient(0deg, rgba(13, 3, 16, 0.7) 0%, rgba(13, 3, 16, 0.06) 42%, rgba(13, 3, 16, 0.24) 100%);
}

.video-scene-grid {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: 0.22;
  background:
    linear-gradient(rgba(255, 255, 255, 0.11) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.11) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: linear-gradient(90deg, black 0%, black 44%, transparent 76%);
}

.video-scene-beam {
  position: absolute;
  z-index: 3;
  pointer-events: none;
  width: 44%;
  height: 130%;
  top: -15%;
  background: linear-gradient(90deg, transparent, rgba(255, 114, 220, 0.4), transparent);
  filter: blur(12px);
  transform: skewX(-18deg) translateX(-160%);
}

.beam-one {
  animation: videoSceneSweep 4.2s ease-in-out infinite;
}

.beam-two {
  width: 28%;
  opacity: 0.7;
  animation: videoSceneSweep 5.8s ease-in-out 1.4s infinite;
}

.hero-copy-layer,
