}

.ugc-orbit {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
}

.ugc-card {
  position: absolute;
  width: clamp(118px, 10vw, 158px);
  min-height: clamp(152px, 13vw, 198px);
  display: grid;
  align-content: end;
  gap: 7px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 24px;
  padding: 14px;
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.18), rgba(255, 255, 255, 0.04)),
    rgba(29, 8, 38, 0.58);
  box-shadow:
    0 22px 56px rgba(0, 0, 0, 0.34),
    0 0 32px rgba(255, 78, 120, 0.22);
  color: #fff;
  backdrop-filter: blur(14px);
  animation: ugcFloat 5.6s ease-in-out infinite;
}

.ugc-card::before {
  position: absolute;
  inset: 10px;
  z-index: -1;
  border-radius: 18px;
  background:
    radial-gradient(circle at 68% 23%, rgba(255, 78, 120, 0.7), transparent 22%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.14), transparent 46%),
    linear-gradient(145deg, rgba(139, 92, 246, 0.34), rgba(255, 131, 94, 0.18));
  content: "";
}

.ugc-card::after {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(110deg, transparent 0 38%, rgba(255, 255, 255, 0.18) 50%, transparent 62% 100%);
  transform: translateX(-120%);
  animation: cardShine 3.8s ease-in-out infinite;
  content: "";
}

.ugc-card span {
  width: fit-content;
  border-radius: 999px;
  padding: 5px 8px;
  background: rgba(255, 78, 120, 0.9);
  color: #fff;
  font-size: 11px;
  font-weight: 950;
}

.ugc-card b {
  position: relative;
  z-index: 1;
  font-size: clamp(14px, 1vw, 16px);
  line-height: 1.05;
}

.ugc-card small {
  position: relative;
  z-index: 1;
  color: rgba(255, 255, 255, 0.7);
  font-size: 12px;
  font-weight: 850;
  line-height: 1.2;
}

.ugc-card i {
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 50px;
  height: 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
}

.ugc-card i::after {
  display: block;
  width: 64%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ff4e78, #ff835e);
  animation: miniProgress 2.8s ease-in-out infinite alternate;
  content: "";
}

.card-hook {
  right: 13%;
  top: 8%;
  transform: rotate(5deg);
}

.card-avatar {
  right: 29%;
  top: 22%;
  transform: rotate(-4deg);
  animation-delay: 0.45s;
}

.card-script {
  right: 7%;
  top: 34%;
  transform: rotate(4deg);
  animation-delay: 0.9s;
}

.card-caption {
  right: 25%;
  bottom: 13%;
  transform: rotate(3deg);
  animation-delay: 1.2s;
}

.card-plan {
  right: 5%;
  bottom: 18%;
  transform: rotate(-5deg);
  animation-delay: 1.55s;
}

.generation-panel {
  position: absolute;
  right: clamp(32px, 4vw, 62px);
  bottom: clamp(94px, 10vh, 138px);
  width: min(370px, 31vw);
  display: grid;
  gap: 9px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 18px;
  padding: 16px;
  background: rgba(21, 6, 27, 0.72);
  color: #fff;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(16px);
}

.generation-panel span,
