}

.generation-meter {
  height: 12px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
}

.generation-meter i {
  display: block;
  width: 74%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ff4e78, #ff835e);
  animation: generationPulse 2.8s ease-in-out infinite alternate;
}

.hero-proof-layer {
  position: absolute;
  left: clamp(30px, 4vw, 62px);
  right: clamp(30px, 4vw, 62px);
  bottom: clamp(24px, 3vw, 40px);
