@keyframes videoSceneBreath {
  from {
    transform: scale(1.01) translate3d(0, 0, 0);
  }

  to {
    transform: scale(1.065) translate3d(-1.6%, -1%, 0);
  }
}

@keyframes videoSceneSweep {
  0%,
  20% {
    opacity: 0;
    transform: skewX(-18deg) translateX(-160%);
  }

  43% {
    opacity: 1;
  }

  78%,
  100% {
    opacity: 0;
    transform: skewX(-18deg) translateX(270%);
  }
}

@keyframes ugcFloat {
  0%,
  100% {
    translate: 0 0;
  }

  50% {
    translate: 0 -16px;
  }
}

@keyframes cardShine {
  0%,
  42% {
    transform: translateX(-120%);
  }

  70%,
  100% {
    transform: translateX(120%);
  }
}

@keyframes miniProgress {
  from {
    width: 42%;
  }

  to {
    width: 86%;
  }
}

@keyframes generationPulse {
  from {
    width: 48%;
  }

  to {
    width: 96%;
  }
}

