/* Studio palette: extend Pokaya purple brand while keeping a clean studio layout. */
:root {
  --studio-purple-950: #18001f;
  --studio-purple-900: #260032;
  --studio-purple-800: #3a004d;
  --studio-purple-700: #4b005e;
  --studio-purple-600: #65007d;
  --studio-pink: #ff3f6e;
  --studio-coral: #ff7a5c;
  --studio-yellow: #ffd21a;
  --studio-shell: #fff7fb;
  --studio-lilac: #f6ecff;
  --studio-card: #ffffff;
  --studio-ink: #2d0d35;
  --studio-muted: #7b687f;
  --studio-line: rgba(75, 0, 94, 0.12);
  --studio-shadow: 0 24px 70px rgba(75, 0, 94, 0.12);
}

.studio-shell {
  background:
    radial-gradient(circle at 86% 0, rgba(255, 63, 110, 0.14), transparent 30%),
    linear-gradient(135deg, var(--studio-shell) 0%, var(--studio-lilac) 100%) !important;
  color: var(--studio-ink) !important;
}

.public-shell .promo-bar {
  width: calc(100% + clamp(36px, 8vw, 128px));
  min-height: 54px;
  margin: 0 calc(clamp(18px, 4vw, 64px) * -1);
  padding: 11px clamp(18px, 4vw, 64px);
  border-bottom: 0;
  border-radius: 0;
  color: #fff !important;
  background:
    linear-gradient(90deg, #ff3f6e 0%, #ff5d6f 48%, #ff7a5c 100%) !important;
  box-shadow: 0 18px 38px rgba(255, 63, 110, 0.2) !important;
  font-size: clamp(18px, 2vw, 30px);
  font-weight: 950;
  line-height: 1.15;
}

.public-shell .promo-bar svg {
  flex: 0 0 auto;
  color: rgba(255, 255, 255, 0.95);
  stroke-width: 3;
}

.promo-copy {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: 5px;
}

.promo-copy strong {
  color: #ffe562;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0;
  text-shadow: 0 2px 12px rgba(75, 0, 94, 0.22);
  white-space: nowrap;
