/* Studio Density System execution: compact operator-scale workspace. */
.studio-shell {
  --studio-sidebar-width: 304px;
  --studio-page-pad-x: clamp(24px, 2.6vw, 42px);
  --studio-page-pad-y: clamp(22px, 2.4vw, 34px);
  --studio-section-gap: 20px;
  --studio-card-pad: clamp(20px, 2vw, 30px);
  --studio-card-radius: 18px;
  --studio-inner-radius: 14px;
  --studio-control-height: 50px;
  --studio-button-height: 46px;
  --studio-h1: clamp(34px, 3vw, 48px);
  --studio-h2: clamp(22px, 2vw, 30px);
  --studio-card-title: clamp(18px, 1.55vw, 23px);
  --studio-body: 15px;
  grid-template-columns: var(--studio-sidebar-width) minmax(0, 1fr) !important;
}

